/* ETHERION 카드 번역 — English (카드 ID → n 이름 · t 마법 글 · f 서사 · k 종류 · b 핸드 짧은 문구 · h 한국어 원문 지문).
   한국어 원문(카드 데이터)이 기준이다. 검사: node tools/i18n/check.js */
"use strict";
const I18N_CARDS = {
"A1-01": {"n":"Pact Curse Doll","f":"A doll stitched with contract scraps for stuffing. Each time a needle goes in, someone who signed in Noctar flinches.","k":"Curse Doll","h":"1nsb97b"},
"A1-02": {"n":"Shadow Thief","f":"It never walks beneath lamplight. It steals its mark's shadow before the purse.","k":"Black Cat","h":"7ulnrj"},
"A1-04": {"n":"Blood Bat Swarm","f":"They hang from the ceiling of the Noctar archives. No one asks whom the scribes call when the ink runs short.","k":"Vampire Bat","h":"137jo4e"},
"A1-05": {"n":"Noctar Ghoul","f":"Those who die in debt rise again in Noctar's back alleys. They forget what they owed, but never the hunger.","k":"Ghoul","h":"194mxkc"},
"A1-06": {"n":"Forfeit Shadow","f":"A shadow someone paid to Morkas. Its owner feels bare underfoot even at noon, and the shadow roams Noctar each night seeking its owner.","k":"Forfeit Shadow","h":"53n8r7"},
"A1-07": {"n":"Shadow Doppelganger","f":"In the shade of Mork Gorge, it borrows the shape of whoever it meets. The original always pays for the loan.","k":"Doppelganger","h":"12nepl7"},
"A1-08": {"n":"Pact Succubus","f":"She comes in dreams, holding out a contract. You wake with a scale mark on your palm that will not fade.","k":"Succubus","h":"1ni9v7e"},
"A1-09": {"n":"Mork Shadow Spider","f":"Whatever falls to the gorge floor, it counts as caught in its web. Spun of shadow, the threads vanish in lamplight and pull taut again when the lamp dies.","k":"Shadow Spider","h":"1x8p1s3"},
"A1-11": {"n":"Pact Rat Soldier","f":"A common soldier of the Abyss Pact. Even to the common, Morkas returns exactly the power they offer.","k":"Rat","h":"1o2e59f"},
"A1-13": {"n":"Noctar Dullahan","f":"He was the executioner who struck oath-breakers from the ledger. Since he paid with his own head, the head under his arm reads the ledger, and the body takes what is owed.","k":"Dullahan","h":"6jt0t2"},
"A1-15": {"n":"Bloodsip Blade","f":"Forged at the edge of the Abyssal Veil. It remembers the taste of each owner's blood and demands the same price of the next.","k":"Cursed Sword","h":"9ssxwn"},
"A1-17": {"n":"Banshee of Morkas","f":"The wail that carries the faceless Shadow King's word. When she weeps at a door, that house's contract falls due today.","k":"Banshee","h":"zgqp8n"},
"A1-18": {"n":"Shadow Fang","f":"A beast that lives behind Noctar's shadow theater. That is why the screams on stage are so often not acting.","k":"Shadow Beast","h":"19wa18g"},
"A1-21": {"n":"Blood Lamia","f":"Coiled beneath Morkas's altar, she counts the blood offered. If it falls short, she collects the rest from the giver.","k":"Lamia","h":"1azzlbn"},
"A1-23": {"n":"Pact Reaper","f":"He goes about collecting contracts that have come due. Where his scythe passes, only signatures remain.","k":"Reaper","h":"160ecoy"},
"A1-24": {"n":"Moonless Werewolf","f":"He chose the new moon over the full when he bargained with Morkas. He may turn on any moonless night, but the price is never seeing a full moon again.","k":"Werewolf","h":"17l3qu9"},
"A1-25": {"n":"Veil Cerberus","f":"The hound guarding the gate of the Abyssal Veil. It never barks at those going in; its three heads take turns sniffing what those coming out left behind.","k":"Hellhound","h":"o3oenf"},
"A1-27": {"n":"Noctar Blood Lord","f":"The lord who holds the keys to the Noctar archives. All the blood that flows in the city passes through his ledger.","k":"Vampire","h":"2n5b2z"},
"A1-28": {"n":"Untearable Contract","f":"A contract that walked out of the Noctar archives on its own. All who try to tear it find themselves writing their name on the signature line.","k":"Contract","h":"wz1ver"},
"A1-29": {"n":"Abyssal Eoduksini","f":"An eoduksini returned from a long stay deep within the Veil. With each step it takes, a roadside lamp goes out.","k":"Eoduksini","h":"16lae85"},
"A1-30": {"n":"Blade of Morkas","f":"The sword of a swordsman who gave his name to the Silent Lord. He vanished long ago; now the blade, carved with a closed eye, goes cutting alone.","k":"Cursed Sword","h":"1ai7p40"},
"A1-31": {"n":"Blood Duke","f":"The oldest blood among Noctar's nobles. Guests at his feast receive an oath scroll instead of a cup.","k":"Vampire","h":"12c97um"},
"A1-32": {"n":"Cursed Legion Lich","f":"He staked his life on a single contract and filed it deep in the Noctar archives. So the cursed legion he leads has no reason to stop marching.","k":"Lich","h":"1mkx9gj"},
"A1-34": {"n":"Enforcer of the Price","f":"Morkas always keeps a deal. When the other party does not, making them keep it is the enforcer's work.","k":"Faceless One","h":"320qd3"},
"A1-35": {"n":"Nightmare of Mork","f":"The black horse from tales the gorge's children hear before sleep. Adults cut the tale short on purpose: a child who hears it to the end hears hoofbeats in their dreams.","k":"Nightmare","h":"8xyj6s"},
"A1-41": {"n":"Chained Wraith","f":"A soul bound to Noctar in place of an unpaid debt. It cannot hold a blade, but harm it and the contract bills the one who did.","k":"Wraith","h":"91oo9b"},
"A1-42": {"n":"Obsidian-Clad Skeleton","f":"Only the armor of the gorge's black stone remains; inside is empty. Its wearer paid for that armor with his flesh.","k":"Skeleton","h":"nc7ssg"},
"A1-43": {"n":"Scale of Closed Eyes","f":"The scale, symbol of Morkas, given a body. Eyes shut, it weighs only the weight of whoever steps on, and stacks every blow it takes on one pan.","k":"Scale","h":"1apizcj"},
"A2-01": {"n":"Novice's Prayer Candle","f":"A novice's first prayer in Elad, the Dawnhold, rose up as a candle. Its flame is only finger-sized, yet it burns away every taint in the wounds it touches.","k":"Candle Spirit","h":"1uzzhq3"},
"A2-03": {"n":"Dawn Lark Flock","f":"They wake before the sun and sing atop Elad's walls. The Celestials on the walls believe that if even one oversleeps, morning comes a little late.","k":"Lark","h":"1ssjrlm"},
"A2-04": {"n":"Downy Dove Chick","f":"A dove chick whose wings are a few tufts of down. Each time it falls, a warm light from somewhere catches it.","k":"Dove","h":"10e5dwa"},
"A2-05": {"n":"Heraldic Eagle","f":"An eagle said to have flown out of the Order of Radiance's banner. Its place on the banner is still empty.","k":"Heraldic Beast","h":"1yy04nh"},
"A2-06": {"n":"Wandering Halo","f":"A masterless halo circling the highland shrines one by one. It seeks a head worthy of it, but none has fit yet.","k":"Halo","h":"n6g7p3"},
"A2-07": {"n":"Oathsworn Valkyrie","f":"She swore one oath before Solante and received a spear. She does not come for the fallen; she descends before they fall.","k":"Valkyrie","h":"ua8mv6"},
"A2-09": {"n":"Dawn Rooster Warden","f":"The lowest rank of the Order of Radiance. Yet always its front rank, too.","k":"Rooster","h":"s32no8"},
"A2-11": {"n":"Young Unicorn","f":"Its horn is still a finger long. Even so, shadows cannot linger where it points.","k":"Unicorn","h":"1t791en"},
"A2-13": {"n":"Radiant Glass Knight","f":"A knight painted on a Dawnhold cathedral window walked out, glass and all. Sunlight passing through splits into seven colors and washes the taint from wounds.","k":"Stained-Glass Knight","h":"jokej2"},
"A2-15": {"n":"Solante's Oathkeeper","f":"A statue that swore its whole life to Solante. Knowing a broken oath meets no mercy, it stands all the firmer.","k":"Holy Statue","h":"q9pe73"},
"A2-16": {"n":"Dawn Patrol Lion","f":"It roams the highland in the darkest hour before dawn. When the sun rises, the path its mane passed brightens first.","k":"Dawn Lion","h":"trt5eg"},
"A2-17": {"n":"Truth-Seeking Sphinx","f":"It asks one question of all who enter Elad. A wrong answer is fine; a lie keeps the gate shut.","k":"Sphinx","h":"oswpor"},
"A2-20": {"n":"Albatross Wingknight","f":"Wings spread, it is as wide as a city gate. Only once every comrade is beneath them does it draw its sword.","k":"Albatross","h":"i5vig"},
"A2-21": {"n":"Oathkeeping Swan","f":"A bird that never changes mates, so it keeps others' oaths too. With so many tucked under its wings, it always looks a little heavy.","k":"Swan","h":"1hto6m9"},
"A2-22": {"n":"Dawn-Ringing Bell","f":"Centuries of Dawnhold morning prayers gathered in a single bell. They say the sun climbs the walls at its first toll, and the sun mostly obliges.","k":"Bell Spirit","h":"1yi7viv"},
"A2-24": {"n":"Light-Returning Mirror","f":"A mirror that gathered dawnlight in the cathedral cloister. Whatever flies at it, light or blade, goes back the way it came.","k":"Mirror Spirit","h":"1jeoy6b"},
"A2-25": {"n":"Holy Flame of Elad","f":"A fire never once extinguished on Elad's cathedral altar. Kindled beside the fallen, it first burns the taint seeped into their wounds.","k":"Holy Flame Spirit","h":"138yqs1"},
"A2-27": {"n":"Dawn Unicorn","f":"A unicorn that runs with the rising sun on its back. Its horn shines only before those who broke an oath.","k":"Unicorn","h":"10gr5rp"},
"A2-28": {"n":"Plaza Saint Statue","f":"The saint's statue in the heart of Dawnhold's plaza awoke. Even as it steps off its plinth to fight, the plaza's doves stay on its shoulders.","k":"Holy Statue","h":"5z5heq"},
"A2-29": {"n":"Valkyrie Captain","f":"The longest-serving of Dawnhold's valkyries. Every stone of its walls bears a morning she defended.","k":"Valkyrie","h":"1p3jqnd"},
"A2-30": {"n":"Dawn Three-Legged Crow","f":"The three-legged crow that basked closest to Solante's light. Its wings blaze like fire, yet never burn the comrades beside it.","k":"Three-Legged Crow","h":"10wrkwq"},
"A2-31": {"n":"Four-Faced Cherub","f":"Four faces watch four ways. Whichever way an oathbreaker flees, one face meets their eyes.","k":"Cherub","h":"1eciud9"},
"A2-33": {"n":"Stained-Glass Guardian","f":"The cathedral's great window, painted with a wing-shielded angel, awoke whole. Even cracked, no light through it leaks away.","k":"Stained-Glass Knight","h":"15b60q0"},
"A2-34": {"n":"Morning Star of Elad","f":"The star that rises over Elad before the sun took form. Where it rests, no shadow falls for three days.","k":"Morning Star Spirit","h":"d52a3a"},
"A2-36": {"n":"Archangel of Dawn","f":"The archangel first to receive Solante's dawnlight. When he spreads his wings, morning comes to the whole highland.","k":"Archangel","h":"5hizpw"},
"A2-41": {"n":"Charging Pegasus","f":"It folds its wings and runs the highland. It could fly, but would rather charge and ram.","k":"Pegasus","h":"1b0it1v"},
"A2-42": {"n":"Executor of Wrath","f":"Light sent down upon oathbreakers. His single stroke falls from a blade taken from the New Moon, so the wounds never stop bleeding.","k":"Judgment Spirit","h":"g1yi3h"},
"A2-43": {"n":"Flamewing Martyr","f":"A pelican that burned its own wings into light. That fire also burns the taint in the wounds of comrades beside it.","k":"Pelican","h":"2j8ins"},
"A3-01": {"n":"Needle Spire Novice","f":"A novice archer on the Needle Spire's lowest floor, memorizing the names of the winds first. She is taught that an arrow that cannot read the wind loses its way before the target.","k":"Hare","h":"1xvd3gr"},
"A3-02": {"n":"Young Harpy","f":"A harpy chick nesting under the Needle Spire's eaves. Building her nest from fletching the Archers' Guild threw away, she first learned to find armor gaps with a single feather.","k":"Harpy","h":"17kqwmi"},
"A3-04": {"n":"Watchtower Owl","f":"It guards the horizon all night from the Needle Spire's watchtower. Archers say eyes age before the bow, but this star-like owl's eyes never do.","k":"Star Owl","h":"m1tptx"},
"A3-05": {"n":"Wind Sylph","f":"Light as a feather, it crosses the plateau counting the enemy. By the time it seems spotted, it has already turned back into wind.","k":"Sylph","h":"1l3tsg6"},
"A3-07": {"n":"Gust Imp","f":"A little spirit with a temper quicker than the wind. Before the archers finish drawing, it snatches the arrow and hits the mark first.","k":"Imp","h":"umhiwa"},
"A3-09": {"n":"Needle Spire Birdfolk","f":"A bird-person living on the outer wall of Belumir's Needle. Flying up and down instead of taking the stairs, it set up a target on every floor.","k":"Birdfolk","h":"jn8ow5"},
"A3-10": {"n":"Quill Harpy","f":"It plucks its own wing feathers and shoots them as arrows. It learned to shoot but not yet to save, so feathers pile like snow wherever it passes.","k":"Harpy","h":"xq8luc"},
"A3-11": {"n":"Griffin Chick","f":"It learns to fly between the plateau shrines and the Needle Spire. Trust it with news, and it arrives before the news does.","k":"Griffin","h":"mndx07"},
"A3-13": {"n":"Storm Hippogriff","f":"It spreads its wings only beneath dark clouds. Rain follows wherever it passes.","k":"Hippogriff","h":"1mip9ue"},
"A3-15": {"n":"Marten Sniper","f":"Knowing every wind has a name, one shot is enough. When other archers blame the wind, he calls it.","k":"Marten","h":"1qxjgq2"},
"A3-16": {"n":"Gapseeker Falcon","f":"It sees only the joints of armor. Its talons do not pierce steel; they slip through the gap steel leaves.","k":"Falcon","h":"1fy3gu1"},
"A3-18": {"n":"Gemini Archer","f":"The twin stars of the night sky came down holding two bows. One star's arrow rides the exact path of the other's.","k":"Constellation","h":"1jtkjly"},
"A3-19": {"n":"Storm Tower Birdfolk","f":"The first bird-person to become a full archer of the Storm Tower's Archers' Guild. Called arrogant, it replies that it learned from the elves.","k":"Birdfolk","h":"mbgpna"},
"A3-20": {"n":"Belumir's Open Book","f":"Belumir's emblem, the open book, has taken form. Star letters rise on every page the wind turns, reading past armor to what lies within, and piercing it.","k":"Grimoire","h":"1bzcenm"},
"A3-22": {"n":"Windrider Griffin","f":"It weighs the air with its feather tips. When it folds its wings the wind stills too, and in that lull it dives.","k":"Griffin","h":"mol3py"},
"A3-23": {"n":"Belumir's Star Fox","f":"It walked the Constellation Plateau all its life with archers seeking Ivel's Library. They never found it, but starlight from its tail marks every path on the plateau.","k":"Star Fox","h":"1kgaald"},
"A3-24": {"n":"Thunderbolt Tengu","f":"It takes up the bow only beneath thunderclouds. One sweep of its feather fan, and lightning settles on the arrowhead.","k":"Tengu","h":"jhyxvu"},
"A3-26": {"n":"Stormhunt Hippogriff","f":"A hunter roaming the plateau in the wake of storms. Beasts the storm drives and foes hiding behind it alike belong to its talons.","k":"Hippogriff","h":"1bpqw8k"},
"A3-28": {"n":"Shooting Star Imp","f":"A little one that fell clinging to a shooting star. Not knowing the way back, it waves from the Needle Spire's top whenever a star passes.","k":"Imp","h":"15w6b12"},
"A3-29": {"n":"Drawing Sagittarius","f":"The constellation Storm Tower archers look up to when first taking a bow. On the night Sagittarius looses, the Guild picks the year's first target.","k":"Constellation","h":"18545zx"},
"A3-30": {"n":"Storm Falcon","f":"A bird that carries storms with it. The rumor that it tamed the Archers' Guild sounds likelier than the reverse.","k":"Falcon","h":"1b5wc0c"},
"A3-31": {"n":"Shard Isles Master","f":"He shot alone for a hundred years in Auragon's Shard Isles, returning only when Sirel's scattering winds could no longer make him miss.","k":"Rock Ibex","h":"1k7oisl"},
"A3-32": {"n":"Whirlwind Tengu","f":"It raises three whirlwinds at once and pierces them with one shot. The Guild calls it skill; the tengu calls it habit.","k":"Tengu","h":"i9pkay"},
"A3-33": {"n":"Star Seeker","f":"A shooting star that soars toward other stars instead of falling. Any star it grazes blinks once that night.","k":"Shooting Star","h":"gu6ts3"},
"A3-34": {"n":"Harpy Queen","f":"A thundercloud always circles her head like a crown. Every harpy under the Needle Spire's eaves hatched in her nest.","k":"Harpy","h":"496qyz"},
"A3-35": {"n":"Skyrender Roc","f":"One spread of its wings parts the clouds. Where it passes, a single rift lingers in the sky.","k":"Roc","h":"1ble6xr"},
"A3-36": {"n":"Storm Tower Master","f":"Master of the Storm Tower's Archers' Guild. The key to the tower Isak built, and its first bow, are now in his hands.","k":"Cloud Giant","h":"1kavdcv"},
"A3-41": {"n":"Still Cloud Whale","f":"An odd whale among wind-things that loves stillness. Cutting gales that enter its cloud body fall silent.","k":"Cloud Whale","h":"qlufbp"},
"A3-42": {"n":"Eye of the Storm","f":"One of the thousand eyes on Belumir's robe, fallen loose. It floats at the storm's heart, glaring calmer the fiercer it blows; the wind cuts down any who draw near.","k":"Thousand Eyes","h":"fhpnx9"},
"B1-02": {"n":"Powder Porter","f":"It climbs Sawtooth Pass hauling powder sacks bigger than itself. Better than anyone, it knows it must never fall.","k":"Ember Mule","h":"lejhgc"},
"B1-03": {"n":"Burning Fuse","f":"Someone in a Fortan powder store lit a fuse and forgot it, and it crawled out on its own. It spreads fire to all it touches and never asks what hangs at its end.","k":"Fuse Spirit","h":"1xe3eay"},
"B1-05": {"n":"Flame Imp","f":"A spark from a Firecrown Range crater grew arms and legs. Fortan goblins find it cute, but before the powder store, they reach for brooms.","k":"Flame Imp","h":"c5m0bb"},
"B1-08": {"n":"Smoke Spirit","f":"The day every battery fired at once, one cloud of gunsmoke refused to clear and took a body. It drifts slowly toward the sound of coughing foes.","k":"Smoke Spirit","h":"olgvio"},
"B1-10": {"n":"Fortan Firehound","f":"A firehound that lives at the gate of the Sawtooth Pass fort. Once it tried to bite the sun; now it has lowered its eyes to the ankles passing by.","k":"Firehound","h":"j5d4nr"},
"B1-12": {"n":"Fire Rat Swarm","f":"Fire rats living in the never-cooling cracks of the Firecrown Range. Their fur won't burn even in flame, so Fortan weaves it into powder-store gloves.","k":"Fire Rat","h":"gaq8xo"},
"B1-13": {"n":"Cinder Bat Swarm","f":"Bats that hung from crater ceilings and grew fat on cinders. When they all take wing, sparks rain from their wings.","k":"Flame Bat","h":"b17w6z"},
"B1-14": {"n":"Rustiron Fire Ape","f":"An ape that plays in the Rustiron Hills, hurling heated stones. No one admits Fortan snipers learned to hide from it.","k":"Fire Ape","h":"1tm9oyn"},
"B1-16": {"n":"Ash Raccoon Sapper","f":"The ash raccoon with Fortan's quickest hands for explosives. Bad at sums, but never once wrong about a fuse's length.","k":"Ash Raccoon","h":"iemlrc"},
"B1-17": {"n":"Battery Tortoise","f":"A lava tortoise with a small crater in the middle of its shell. Fortan gunners hate admitting that hole outranges their cannons.","k":"Lava Tortoise","h":"r56uyd"},
"B1-18": {"n":"Powder Store Fire Ants","f":"Fire ants that tunneled beneath a Fortan powder store. The goblins gave up and let them guard it; the ants think it was always theirs.","k":"Fire Ant","h":"col1go"},
"B1-21": {"n":"Firetusk Boar","f":"A Firecrown Range boar whose tusk tips glow red-hot. Once it charges down Sawtooth Pass it cannot stop, and where it stops is what it hits.","k":"Fire Boar","h":"jrvkqi"},
"B1-22": {"n":"Fire-Breathing Chimera","f":"Near Dormak's Heartfire, three beasts melted into one body. The three heads fight to breathe fire first, so the forest always burns three times.","k":"Chimera","h":"1mkyk4d"},
"B1-24": {"n":"Wolverine Mortarman","f":"It lobs shells high to drop beyond the walls. Its targets see the shadow before they hear the sound.","k":"Wolverine","h":"1l4nnfk"},
"B1-25": {"n":"Siege Toad","f":"A toad that holds lava in its throat sac and spits it over walls. Each spit takes half a day of swelling, so Fortan sings to it meanwhile.","k":"Flame Toad","h":"14dm2fe"},
"B1-26": {"n":"Firecrown Fire Giant","f":"Dormak's Heartfire overflowed down the Firecrown slopes and hardened into a man's shape. Called a giant, it knows best it is less than one of Dormak's fingers.","k":"Fire Giant","h":"1ri92ii"},
"B1-27": {"n":"Blast Ifrit","f":"A fire spirit born from the smoke pillars of the Firecrown Range. When Fortan engineers ask it about powder mixes, it answers only with another scorch mark on the workshop wall.","k":"Ifrit","h":"rm9i1r"},
"B1-30": {"n":"Lava Burrow Worm","f":"A worm that tunnels under the Firecrown Range eating cooled lava. Where it passes, no grass grows the next year.","k":"Lava Worm","h":"m2xrz4"},
"B1-31": {"n":"Firecrown Fire Serpent","f":"A serpent that swims upstream in the lava rivers of the Firecrown Range. Its bite keeps burning long after it leaves.","k":"Fire Serpent","h":"1xiy6e"},
"B1-32": {"n":"Talakus Pitch Horror","f":"Talakus's black blood rose through veins underground and stood up, heated by Dormak's fire. Each step leaves a sticky print, which Fortan scoops into its powder.","k":"Pitch Horror","h":"wmjsle"},
"B1-33": {"n":"Dormak's Crater","f":"One of the vents where Dormak's Heartfire breathed walked away from the mountain. It is quiet as it breathes in; when it breathes out, stones fall from a distant sky.","k":"Crater","h":"zaobzw"},
"B1-34": {"n":"Firecrown Behemoth","f":"What seemed a ridge of the Firecrown Range rose one day and walked. Roads were often renamed after it passed.","k":"Behemoth","h":"ga1gow"},
"B1-36": {"n":"Blazing Lion King","f":"A lion king whose every strand of mane is a fuse. In Fortan, whoever makes the biggest blast rules.","k":"Powder Lion","h":"1ikiaf6"},
"B1-41": {"n":"Ashshell Snail","f":"A snail with a shell of cooled ash and fire inside. It goes a hand's span a day, but a hand that touches its shell throbs all night.","k":"Lava Snail","h":"8jm32g"},
"B1-42": {"n":"Boiling Lava Slime","f":"Lava from a crater floor that never cools or hardens. Shells only make it slosh and swallow; swords come back melted.","k":"Lava Slime","h":"12t2vj"},
"B1-43": {"n":"Fortan Kiln Spirit","f":"Fortan's longest-burning kiln stood up and blocked Sawtooth Pass. Those from the forest went home scorched before its firebox.","k":"Kiln Spirit","h":"1l56ibr"},
"B2-01": {"n":"Rivet Worker","f":"A woodpecker that drives rivets with its beak in the Durkheim workshops. The length of the rivet rows it drives in a day is that day's wage.","k":"Ironbeak Woodpecker","h":"a8x18"},
"B2-02": {"n":"Cogwheel Windup Rat","f":"The windup rat every Durkheim apprentice builds first. The saying that you must lose a fingertip to become a master comes from this rat.","k":"Windup Rat","h":"1dzsb1e"},
"B2-05": {"n":"Durkheim Apprentice","f":"An apprentice fresh to the underground city. He still smells of sunlight, and his seniors sniff and tease him.","k":"Ironclad Pangolin","h":"n9fm65"},
"B2-06": {"n":"Steel Gatekeeper Armor","f":"An empty suit of armor by the workshop door woke on the day the Iron Heart first beat. It still asks those who would enter only one thing: \"Whose beard?\"","k":"Living Armor","h":"1nrrx99"},
"B2-07": {"n":"Walking Rivet Shield","f":"A masterless rivet shield rises on its own to bar the way. A new rivet sprouts in every dent, and once it has blocked, it strikes back down.","k":"Awakened Shield","h":"mji2fl"},
"B2-09": {"n":"Steam Golem","f":"A golem run on a single boiler. Strong, but when the steam runs out it stops on the spot, like a sigh.","k":"Golem","h":"li5mlu"},
"B2-12": {"n":"Apprentice Smith","f":"An apprentice learning the hammer at the anvil. The calluses on his palms grow more like his master's.","k":"Iron Monkey","h":"1qbhxal"},
"B2-15": {"n":"Steelsmith","f":"He hammers iron mined from Sorgrim's sinews. The steel he forges hums even after it cools.","k":"Cyclops","h":"1lassz"},
"B2-16": {"n":"Armored Windup Spider","f":"An eight-legged windup machine in layered plate. It hangs from mine ceilings and will not drop until its job is done.","k":"Windup Spider","h":"12wgfn1"},
"B2-17": {"n":"Ironhorn Goat","f":"A goat that licked the bare veins of the Ironframe Range until its horns grew into iron. The rock it stands on is where the wall ends.","k":"Ironhorn Goat","h":"1me2fdw"},
"B2-18": {"n":"Steam-Snort Bull","f":"A bronze bull cast by Durkheim's artisans, a boiler seated in its belly. One snort makes the lamps of the underground city flicker.","k":"Bronze Bull","h":"1f6zt93"},
"B2-19": {"n":"Walking Anvil","f":"Durkheim's longest-struck anvil got legs the day the Iron Heart beat. Generations of masters' hammers taught it to return every blow.","k":"Awakened Anvil","h":"1bnzdti"},
"B2-22": {"n":"Iron-Eating Bulgasari","f":"Once no bigger than a needle, the beast grew this large on Durkheim's nails and locks. Felling it takes as much toil as razing a castle.","k":"Bulgasari","h":"1y7ixjg"},
"B2-24": {"n":"Ironframe Gargoyle","f":"A gargoyle that gnaws rusted veins on the cliffs of the Ironframe Range. Perched at a mine mouth it passes for a statue, until wind through its frame draws a low moan.","k":"Steel Gargoyle","h":"a8bmfp"},
"B2-25": {"n":"Workshop Guard Golem","f":"A golem guarding the deepest room of the Durkheim workshops. It is polite not to ask what lies inside.","k":"Golem","h":"chjv5h"},
"B2-26": {"n":"Sorgrim's Iron Rhino","f":"A rhino raised on dark red iron torn from veins where Sorgrim's sinews lie bare. They say the sleeping arm twitches with each step it takes.","k":"Ironclad Rhino","h":"vj3ck4"},
"B2-27": {"n":"Durkheim Guard Captain","f":"The captain guarding Durkheim's gates. Shards of every blade he has stopped are braided into his mane.","k":"Haetae","h":"74oluy"},
"B2-28": {"n":"Flowing Quicksilver","f":"The silver blood flowing among Sorgrim's sinews seeped into the mines. Strike it and it scatters, then gathers again at your feet.","k":"Quicksilver Slime","h":"m2ys8m"},
"B2-30": {"n":"Ironframe Wyvern","f":"An iron-scaled wyvern circling over the bare veins of the Ironframe Range. As if it knows Feros, the dragon who does not fly, watches from deep below, it rarely lands.","k":"Iron Wyvern","h":"3rn68i"},
"B2-32": {"n":"Walking Iron Fortress","f":"Durkheim's artisans put legs on a fortress. It has never fallen, but half the city had to be dug anew to fit it through the gates.","k":"Siege Engine","h":"jpfri2"},
"B2-33": {"n":"Ordun's Bone Knight","f":"Armor made of grey Adamant from Ordun's spine stood up with no one inside. A knight of a giant's bones does not know how to kneel.","k":"Living Armor","h":"7tmew5"},
"B2-34": {"n":"Great Steam Colossus","f":"A steam colossus with a furnace for a heart. When it exhales, the whole mine sinks in white vapor.","k":"Colossus","h":"1d2mteq"},
"B2-35": {"n":"Durkheim Grandmaster","f":"The grandmaster who leads the Durkheim workshops. Since the Ironheart Swallower, no one's trunk has shaped more golems.","k":"Iron Elephant","h":"nksr02"},
"B2-36": {"n":"Bronze Guardian Giant","f":"A guardian giant Durkheim cast in bronze. Pull one nail from its ankle and it falls, they say, but no one has yet reached that nail.","k":"Bronze Giant","h":"xsdsp6"},
"B2-41": {"n":"Runaway Windup Doll","f":"A doll let loose with its spring wound far too tight. It does not know how to stop, so all it can do is crash.","k":"Automaton","h":"1d5m0di"},
"B2-42": {"n":"Overheated Press","f":"A press that flattened ingots went mad from the heat. Now it flattens whatever is before it.","k":"Automaton","h":"6qybq5"},
"B2-43": {"n":"Self-Destruct Automaton","f":"An automaton engraved with one final order. Everyone knows what that order is, so no one stands beside it.","k":"Automaton","h":"1kn08gn"},
"B3-02": {"n":"Capacitor Apprentice","f":"Hauls capacitor jars and learns to handle lightning. Wool that always points skyward marks an apprentice.","k":"Shock Sheep","h":"cfgg7i"},
"B3-03": {"n":"Lightning Firefly Swarm","f":"Fireflies gather wherever Keraun's nerves spark above ground. Voltarium children jar them as lanterns, and their hair stands up.","k":"Firefly","h":"1fvc1s1"},
"B3-04": {"n":"Static Sprite","f":"A fingernail-sized sprite born between fur and amber. It hides in every doorknob and giggles with a zap when a hand touches.","k":"Spark Fairy","h":"5wjq5j"},
"B3-05": {"n":"Voltarium Scholar","f":"Fresh into the Thunder Academy. The first exam: get struck by lightning without dropping your notebook.","k":"Meerkat","h":"196goe9"},
"B3-06": {"n":"Thunderbird Chick","f":"Just hatched in the storm clouds of Thunderroar Plateau. Its wingbeats are clumsy, but sparks already fly from its feathers.","k":"Thunderbird","h":"1cj76jq"},
"B3-09": {"n":"Current Glider","f":"Glides between lightning towers, snapping copper wire wherever it lands. Voltarium's repairmen hate it most.","k":"Flying Squirrel","h":"1a7mqhm"},
"B3-10": {"n":"Lightning Rod Crow","f":"Nests atop Voltarium's lightning towers. Even in storms it stays, waiting for the bolt to find its nest.","k":"Storm Crow","h":"1jqu96e"},
"B3-12": {"n":"Discharge Sprite","f":"Appears only when stored lightning bursts all at once. That is why Voltarium's lab walls are always freshly painted.","k":"Spark Fairy","h":"11tls30"},
"B3-13": {"n":"Voltarium Homunculus","f":"A tiny person woken by lightning in a glass jar. It records the currents all night; every log ends \"further testing required.\"","k":"Homunculus","h":"8wy0d"},
"B3-14": {"n":"Thunder Eel","f":"Lives on the Rustwater's bed, holding thunder. Fortan's goblins distrust anything without a whiff of powder and never wade in.","k":"Lightning Eel","h":"42bgpz"},
"B3-15": {"n":"Chain Lightning Spirit","f":"A spirit that leaps from one link to the next. Scholars who tried to catch it let go around the third link.","k":"Lightning Spirit","h":"o20t9"},
"B3-16": {"n":"Charge Spider","f":"Spins copper-bright threads among the tower girders. The more its prey struggles, the more lightning it pours into the web.","k":"Shock Spider","h":"f178vb"},
"B3-18": {"n":"Tarsier Engineer","f":"Trusts circuits over gears. Argues all night with Durkheim's smiths, then picks up a hammer with them at dawn.","k":"Tarsier","h":"1b8sc81"},
"B3-20": {"n":"Stormsting Scorpion","f":"Gathers lightning in its tail on Thunderroar Plateau. Some blueprints copied from that tail are banned even at the Academy.","k":"Lightning Scorpion","h":"1tyo194"},
"B3-22": {"n":"Shock Sentinel","f":"A lightning guardian set above Voltarium's gate. It notices an approacher's iron first.","k":"Thunder Engine","h":"ujrdl2"},
"B3-23": {"n":"Professor in a Jar","f":"The Academy's longest lecturer shed his body for a jar. Lectures grew longer; dozing students still wake to a jolt.","k":"Brain in a Jar","h":"1x6suyv"},
"B3-24": {"n":"Flash Moth","f":"Opens its wings only when lightning strikes. One flap bursts with blinding light; a scholar who peered close went blind for days.","k":"Lightning Moth","h":"5hs1n6"},
"B3-25": {"n":"Keraun's Bolt Spirit","f":"On nights Keraun dreams, lightning leapt up his nerves and took form. Every needle in its path goes mad.","k":"Lightning Spirit","h":"rcaa0j"},
"B3-26": {"n":"Doctor of Thunder","f":"A giant salamander who earned a doctorate by surviving lightning strikes. The scars on its body are its diploma.","k":"Giant Salamander","h":"15lnftb"},
"B3-27": {"n":"Great Capacitor","f":"A huge capacitor beneath Voltarium. Everyone dreads the day its lightning is released at once.","k":"Capacitor","h":"1wwgtvc"},
"B3-29": {"n":"Keraun's Thundercloud","f":"A dark cloud that never leaves Thunderroar Plateau. Spells cast beneath it get a handful of lightning added.","k":"Thundercloud","h":"oynd1"},
"B3-31": {"n":"Shock Fortress","f":"A fortress walled with lightning instead of stone. Those nearing Voltarium feel their hair rise before they reach the fence.","k":"Thunder Tower","h":"bgvujq"},
"B3-32": {"n":"Thunderstorm Giant","f":"Auragon's scattered breath met the plateau's lightning and gathered into a giant. With every step the sky rumbles in answer.","k":"Storm Giant","h":"1mzwmqj"},
"B3-33": {"n":"Voltarium Dean","f":"Head of Voltarium's Thunder Academy. The first to dream of bottling Astrak's lightning.","k":"White Crane","h":"fm7jgd"},
"B3-34": {"n":"Blast Engine","f":"Gathers lightning and unleashes it in one burst. Gnomes know when to duck just by how it breathes.","k":"Thunder Engine","h":"1qk7w18"},
"B3-36": {"n":"Thunder Beast","f":"Said to fall from the sky with the thunderbolt. Where it crouches, Voltarium's machines spin harder on their own.","k":"Thunder Beast","h":"dbf732"},
"B3-41": {"n":"Insulated Warden","f":"Wrapped in rubber and porcelain so lightning slips past. Voltarium ranks it its most boring invention.","k":"Thunder Engine","h":"1lxns9r"},
"B3-42": {"n":"Barbed Cloud Jelly","f":"Drifts among storm clouds, channeling bolts to earth with its tentacles. Whoever touches it becomes the bolt's path.","k":"Cloud Jellyfish","h":"3l4ck4"},
"C2-1": {"n":"Novice Shortbow","f":"The short bow first given to Needle Spire novices. It strikes with wind instead of fists.","h":"1kol828"},
"C3-1": {"n":"Storm Bow","f":"A bow with a small storm wound in its string. Lightning arrows spark even undrawn.","h":"17pu9rz"},
"C4-1": {"n":"Star-Reading Orb","f":"The orb Isak used to read the stars' script. A bolt, once sparked, finds its next target itself.","h":"nacnko"},
"CS-A1": {"n":"Silent Possession","t":"The enemy's front 1 spell becomes [Nullify]. 1 enemy unit with the highest remaining HP gets [Possess] — its remaining HP becomes the remaining HP of the lowest-Level other unit on the Field (only if lower).","f":"The chanting mouth falls silent, and the frailest soul settles into the stoutest body. Under Morkas's new moon, both are worth the same.","b":"{Foe spell 1} [Nullify]|{Foe top ♥ 1} ♥ = ♥ of lowest Level on Field","h":"1icd01x"},
"CS-A2": {"n":"Purifying Light","t":"[Nullify] the enemy's front 1 spell. Allied front unit: ATK +2, [Barrier].","f":"Under Solante's light, nothing stays hidden. Exposed traps vanish, and light rests on the spearpoint of the leading knight.","b":"{Foe spell 1} [Nullify]|{Ally front 1} ⚔+2 [Barrier]","h":"ue6ect"},
"CS-A3": {"n":"Spell Break","t":"[Nullify] the enemy's front spell (1 card).","f":"Storm Tower novices learn to break spells before casting them. Those who cannot break another's spell may not climb the tower.","b":"{Foe spell 1} [Nullify]","h":"bl8lxr"},
"CS-B1": {"n":"Burn the Traps","t":"Front enemy spell 1: [Nullify]. Enemy front 2 units: HP −1.","f":"Goblins don't disarm traps. They toss in fire and watch them go off. Whoever stood by the trap ends up watching too.","b":"{Foe spell 1} [Nullify]|{Foe front 2} ♥−1","h":"1pjqta4"},
"CS-B2": {"n":"Sealing Wedge","t":"[Nullify] the opponent's front spell (1 card).","f":"Burned by spells a few times, the dwarves made iron wedges. A spell pinned by a Durkheim wedge never opens again.","b":"{Foe spell 1} [Nullify]","h":"1dyvs95"},
"CS-B3": {"n":"Short Circuit","t":"[Nullify] the enemy's front 1 spell.","f":"Every spell is a current in the end. A Voltarium gnome just lays one copper wire across its path.","b":"{Foe spell 1} [Nullify]","h":"1z0htia"},
"CS-G1": {"n":"Trap Stomp","t":"[Nullify] 1 front enemy spell.","f":"Garun's orcs don't know how to avoid traps. They do know how to stomp them flat before they spring.","b":"{Foe spell 1} [Nullify]","h":"1dh2bw4"},
"CS-G2": {"n":"Moss Cover","t":"[Nullify] the front-most enemy spell (1 card). If nullified, 2 front-most allied units: ATK +1, HP +2.","f":"Moss covers anything. Smothered spells choke out, and the wounds of trolls who tread on it regrow beneath the moss.","b":"{Foe spell 1} [Nullify]|If nullified, {Ally front 2} ⚔+1 ♥+2","h":"v5eydm"},
"CS-G3": {"n":"Song of Cleansing","t":"[Nullify] the enemy's front-most 1 spell. If nullified, all enemy units lose [Barrier]·[Thorns]·[Curseproof]·[Guard] and ATK −1.","f":"The Wellspring Maidens' song washes away what was cast. When a spell melts into water, the blessings and resolve of those who trusted it wash away too.","b":"{Foe spell 1} [Nullify]|If so, {All foes} remove ⚔−1","h":"18wyiq"},
"EP-A1-1": {"n":"Abyss Blade Dancer","f":"A mantis that dances in Noctar's shadow theater. When the dance ends, the audience is one fewer.","k":"Mantis","h":"1xdehmc"},
"EP-A1-2": {"n":"Noctar Headsman","f":"Chief of the executioners who go to collect oath-breakers. One swing, and those in line fall one after another.","k":"Wendigo","h":"12nc1r8"},
"EP-A1-3": {"n":"Veil Executioner","f":"A thing that walked out of the Abyssal Veil. Whoever asks what it left behind is next.","k":"Wraith","h":"39vsj1"},
"EP-A2-1": {"n":"Dawnhold Gate Lamassu","f":"A winged bull carved on Elad's gate pillar. It woke the day the gate first opened, and has never left it since.","k":"Lamassu","h":"qwgjhu"},
"EP-A2-2": {"n":"Twilight Wall Warden","f":"A white wolf guarding the Twilight Wall that faces the Empty Land. Whatever comes from beyond, its job is to meet it first.","k":"White Wolf","h":"dvouyt"},
"EP-A2-3": {"n":"Archangel of Twilight","f":"An archangel said to bear one of Solante's six wings. None beneath it falls before sunset.","k":"Archangel","h":"wliacy"},
"EP-A3-1": {"n":"Needle Spire Sylph","f":"A wind spirit who learned the bow in the Needle Spire's Guild. Being wind itself, it sends only star letters instead of arrows, and they still reach the target.","k":"Sylph","h":"1f05mk5"},
"EP-A3-2": {"n":"Thundercloud Whale","f":"The thundercloud it wears scatters the first blade. While it passes overhead, the lightning allies call falls thicker.","k":"Cloud Whale","h":"1lwiu46"},
"EP-A3-3": {"n":"Sky Cradle Warden","f":"A great star owl guarding the Sky Cradle beyond the Needle Spire's top gate. Even Sirel, the wind dragon, stops her pranks when meeting its gaze.","k":"Star Owl","h":"fgjv9z"},
"EP-B1-1": {"n":"Fortan Grenadier Chief","f":"Throws alone what a hundred grenadiers would. Not a day goes by without the smell of powder.","k":"Fire Ape","h":"18cko5c"},
"EP-B1-2": {"n":"Firecrown Phoenix","f":"A bird that burns to death and wakes again atop the Firecrown Range. It dives at the batteries' fuses below; by the time the smoke clears, it is ash in another nest.","k":"Phoenix","h":"au8s4a"},
"EP-B1-3": {"n":"Dragon-Slayer Cannon","f":"A great cannon Fortan cast to shoot Ignal one day raised its muzzle by itself. It has never fired at a dragon, but its barrel heats whenever it faces the Firecrown Range.","k":"Awakened Cannon","h":"1mnynm5"},
"EP-B2-1": {"n":"Barbed Iron Hedgehog","f":"A hedgehog that ate rivets left in the workshops until its spines grew in iron. All it knows is to block and curl up, and that's the problem.","k":"Iron Hedgehog","h":"1r1cpk3"},
"EP-B2-2": {"n":"Steel Crusher Golem","f":"A golem that broke rock in Durkheim's mines, sent off to war. It breaks armor like rock too.","k":"Golem","h":"9vs2g7"},
"EP-B2-3": {"n":"Durkheim Gate Colossus","f":"The underground city's gate itself. Asked if the city is left open when the gate walks off, the workshop master only said, \"The gate comes back.\"","k":"Colossus","h":"1365u2l"},
"EP-B3-1": {"n":"Voltarium Test Subject","f":"Woken by Voltarium's lightning. It bleeds off stray charge to drop incoming shots, and lends the rest to allied spells.","k":"Test Subject","h":"gr344c"},
"EP-B3-2": {"n":"Chain Lightning Serpent","f":"Bite one body and it leaps to the next. Scholars chased the reason all their lives; the serpent has never once stopped.","k":"Lightning Serpent","h":"1azfltu"},
"EP-B3-3": {"n":"Keraun's Lightning Spire","f":"A tower raised on the nerves of the giant sleeping under the plateau. That it walks is the gnomes' stubbornness.","k":"Thunder Tower","h":"10hjivg"},
"EP-G1-1": {"n":"Obsidian Cyclops Brawler","f":"One eye and one obsidian gauntlet won it thirty bouts in the Garun arena. Gorvath opened one eye to watch one of them.","k":"Cyclops","h":"ynll2o"},
"EP-G1-2": {"n":"Woolly Rhino Rider","f":"The only orc a Howling Steppe woolly rhino lets ride. It rams one rank and charges on to the next without stopping.","k":"Woolly Rhino","h":"8h8gys"},
"EP-G1-3": {"n":"Duel King of Throne Peak","f":"A silverback who climbed to Throne Peak, where Gorvath sleeps, to issue a challenge. The dragon never woke, but all it met on the way fell.","k":"Silverback","h":"1ynu0gm"},
"EP-G2-1": {"n":"Thistle Vine Fiend","f":"Thistle and vine, tangled and risen at the edge of the Rusted Marsh. It drank rustwater, and its thorns set hard as iron.","k":"Vine Horror","h":"1gb8elk"},
"EP-G2-2": {"n":"Sylvaniel Bow Dryad","f":"A dryad dwelling on the great-tree city's highest branch. By the time the arrow falls, her perch is hidden in leaves.","k":"Dryad","h":"1iw8zci"},
"EP-G2-3": {"n":"Verdan's Elder Giant","f":"An old tree come down from the Primeval Range. Some say it grew from a branch fallen from Verdan's antlers.","k":"Treant","h":"117rdyo"},
"EP-G3-1": {"n":"Pearlglow Jellyfish","f":"A jellyfish that swallowed the maidens' pearl and gained its glow. One pulse and the water rises to turn blades aside.","k":"Jellyfish","h":"1pdf2h"},
"EP-G3-2": {"n":"Abyssal Naga Lancer","f":"A naga bearing the harpoon said to have pierced Urboa's scales in the Talakus Trench. Thrown, it rides the current back.","k":"Naga","h":"r2rxxj"},
"EP-G3-3": {"n":"Marencia's Archmaiden","f":"She leads the rite renewing the pact with the water dragon Marencia. Strike her, and your hand comes away wet.","k":"Oceanid","h":"zo79j4"},
"G1-01": {"n":"Young Arena Bison","f":"Raised outside the fence of the Garun arena, watching its elders fight. Today it steps inside for the first time.","k":"Bison","h":"tqffws"},
"G1-03": {"n":"Stone-Tossing Baboon","f":"A baboon of the Howling Steppe's rocky hills. It mimicked the slings of Garun's children, and now throws better than they do.","k":"Baboon","h":"1mqudfa"},
"G1-04": {"n":"Hyena Pup","f":"It bites a bone as big as its head and never lets go. Even on nights it loses, it still cackles.","k":"Hyena","h":"1ac92kt"},
"G1-05": {"n":"Steppe Hyena","f":"When the arena roars, they appear from nowhere and circle the fence. Cleaning the bones of finished fights is their share.","k":"Hyena","h":"ed549r"},
"G1-07": {"n":"Steppe Centaur","f":"A hunter who ran the Howling Steppe before the orcs. It runs all day with the wind at its back, and draws its bow only once.","k":"Centaur","h":"1dfhpwt"},
"G1-08": {"n":"Stoneclaw Gargoyle","f":"A stone beast crouched on cliffs along Gorvath's back. Orcs take it for a plain rock until it spreads its wings.","k":"Gargoyle","h":"lhsi7o"},
"G1-10": {"n":"Stonetusk Boar","f":"A steppe boar with tusks hard as stone. It knows no way to stop, and its trail looks like a plowed field.","k":"Boar","h":"mrp24s"},
"G1-11": {"n":"Obsidian Spearman","f":"It lashed obsidian from the foot of Throne Peak to its spear tip. A chipped edge sinks deeper.","k":"Mongoose","h":"rw1txh"},
"G1-12": {"n":"Young Slinger Giant","f":"A rock giant risen from Gorvath's back not even a century ago. Too weak yet to lift mountains, it throws boulders.","k":"Rock Giant","h":"1i441mb"},
"G1-13": {"n":"Gravel Cockatrice","f":"A rooster-headed, serpent-tailed beast that turns what it glares at into gravel. That is why its nest is always ringed with gravel.","k":"Cockatrice","h":"izr5f5"},
"G1-14": {"n":"Charging Minotaur","f":"It rammed through ten orcs in the Garun arena and caught Gorvath's eye. It still learns what is ahead only after the impact.","k":"Minotaur","h":"aw5r3n"},
"G1-15": {"n":"Obsidian-Claw Basilisk","f":"A basilisk that honed its claws biting obsidian below Throne Peak. Meet its eyes and you stiffen; take its scratch and you bleed long.","k":"Basilisk","h":"1vv0e5s"},
"G1-18": {"n":"Ogre Shaman","f":"An ogre with its ear to the ground, waiting for one word from Grom. Its ears beat any orc's, so it claims it caught half the first syllable.","k":"Ogre","h":"ounjor"},
"G1-19": {"n":"Rockback Bear Rider","f":"A bear that slept so long below Throne Peak that rocks lodged in its back. It carries orcs, but the bear decides when to rise.","k":"Bear","h":"1xalwnk"},
"G1-21": {"n":"Obsidian Centaur Archer","f":"A centaur that hunts only chieftains. It notches its bow for each one felled; now the bow is covered in notches.","k":"Centaur","h":"o4e1dd"},
"G1-23": {"n":"War Drum Ogre","f":"An ogre with a bearskin drum strapped to its belly. As the beat quickens, the orcs breathe harder, and its belly booms along.","k":"Ogre","h":"uwyanl"},
"G1-24": {"n":"Hyena Packleader","f":"One laugh gathers the scattered pack. Two laughs scatter the enemy.","k":"Hyena","h":"1w1bnsn"},
"G1-25": {"n":"Child of Gorvath","f":"A rock giant that rose from Gorvath's back in a year of quakes at Throne Peak. Each time it clenches a fist, the ground flinches.","k":"Rock Giant","h":"18qgwv4"},
"G1-26": {"n":"Warlord Turk","f":"He led the Rockfang tribe over Sawtooth Pass three times. Each time he returned, the horde was bigger.","k":"Sabertooth","h":"13cde6"},
"G1-27": {"n":"Mother Cave Bear","f":"She winters with her cubs in a cave of Throne Peak. Come spring, she leaves the den first and stands in front.","k":"Bear","h":"157wyn4"},
"G1-28": {"n":"Steppe Bison Herd","f":"A herd thundering across the Howling Steppe. No one taught them how to stop, and they have no wish to learn.","k":"Bison","h":"z718sa"},
"G1-29": {"n":"Grom's Rock Spirit","f":"Grom, Great Spirit of Earth, spent a century on one word, and the rocks gathered and rose. Even they don't yet know what it was.","k":"Rock Spirit","h":"qut650"},
"G1-32": {"n":"Obsidian Behemoth Lizard","f":"An ox-sized lizard clad in obsidian scales. When it runs, all the steppe grass lies down one way.","k":"Giant Lizard","h":"k5b84h"},
"G1-33": {"n":"Pilgrim Rock Giant","f":"A rock giant climbing from Gorvath's back to Throne Peak's summit. Each step takes a year, so orcs keep their calendar by it.","k":"Rock Giant","h":"194vg4i"},
"G1-34": {"n":"Gorgon of Gorvath","f":"She turns to stone any who would wake Gorvath. Most statues lining Throne Peak's foot were once miners.","k":"Gorgon","h":"1ofqyex"},
"G1-35": {"n":"Quake Wurm","f":"A giant worm burrowing beneath Gorvath's back. A few of Throne Peak's quakes are really its yawns.","k":"Earth Wurm","h":"1reb06g"},
"G1-36": {"n":"Minotaur High Chief","f":"High chief of the minotaur herds. Where he halts becomes that year's battlefield, and the orcs don't bother choosing elsewhere.","k":"Minotaur","h":"1cmt02u"},
"G1-41": {"n":"Shield Ogre","f":"An ogre bearing a great swamp tortoise's shell as a shield. Three orc runts hide behind it at once.","k":"Ogre","h":"1w634f4"},
"G1-42": {"n":"Fallen Scale of Gorvath","f":"A scale shed onto Throne Peak's slopes as Gorvath turned in sleep. While the dragon sleeps, it rises alone to catch blades.","k":"Dragon Scale","h":"1ejkdlt"},
"G1-43": {"n":"Rampart Rock Spirit","f":"A spirit of rocks lined up like a wall at Grom's will. Behind that wall, the orcs learned how to fall back.","k":"Rock Spirit","h":"jnhih3"},
"G2-02": {"n":"Moss Kodama","f":"Forest breath, long pooled in an old tree's shade, took a small body. Trampled, it breaks; when rain comes, it clicks its head and sprouts again.","k":"Kodama","h":"1yt50kv"},
"G2-03": {"n":"Sloth Trainee Archer","f":"It learns the bow on Sylvaniel's lowest branch. Years yet remain before the high ones.","k":"Sloth","h":"1t8968w"},
"G2-04": {"n":"Young Dryad","f":"A dryad just stepped from a vine-wrapped sapling. When someone passes, the vines wake before she does.","k":"Dryad","h":"15wo0jm"},
"G2-05": {"n":"Young Treant","f":"A treant that hasn't learned all its words. Instead, its roots understand the earth's tremors.","k":"Treant","h":"1v4t7rn"},
"G2-08": {"n":"Badger Warden","f":"A badger who buries the forest's fallen beneath the trees. Flowers bloom each year where he digs.","k":"Badger","h":"149xbh6"},
"G2-09": {"n":"Forest Satyr","f":"A satyr bearing a lightning-struck tree's bark as a shield. He pipes, then fights, then pipes again.","k":"Satyr","h":"149ar81"},
"G2-11": {"n":"Parasol Sentry","f":"Mushroomfolk sprouted in rows beneath Sylvaniel's rope bridges. They know a guest by footsteps alone, but always answer a night late.","k":"Mushroomfolk","h":"1o5fhaj"},
"G2-13": {"n":"Elder Tree Spider","f":"It wrapped a whole old tree in silk and made it home. Foes never learn which branch the threads fly from.","k":"Forest Spider","h":"1gsbbuz"},
"G2-15": {"n":"Eilen Stag","f":"A herd that circles the edge of the Great Forest of Eilen. At the sound of an axe, every antler turns that way.","k":"Antlered Deer","h":"1h2lcwj"},
"G2-17": {"n":"Toad Shaman","f":"Chewing moss, he speaks with the forest spirits. Only the trees understand him.","k":"Moss Toad","h":"a6fk2g"},
"G2-20": {"n":"Sylvaniel Tiger","f":"On Covenant council days it lies on every stair of the great-tree city. That day, not even the wind passes without leave.","k":"Forest Tiger","h":"1as8lma"},
"G2-21": {"n":"Treant Warrior","f":"Old treants hate fighting. But a treant that has seen the forest burn is different.","k":"Treant","h":"161uz33"},
"G2-22": {"n":"Thornwood Mandrake","f":"It lives half-buried deep in the Thornwood. Whoever tries to pull it is lost to its scream and never leaves the forest.","k":"Mandrake","h":"1neecpg"},
"G2-23": {"n":"Drien's Apostle","f":"She turns the great forest spirit's memories into song. Those songs hold the names of burned forests, too.","k":"Dryad","h":"pobjys"},
"G2-25": {"n":"Verdan's Fallen Antler","f":"When Verdan shook his head, an antler branch fell on the Primeval Range, took root and stood. Beside it, not one leaf moves without the dragon's leave.","k":"Dragon-Antler Branch","h":"187ophu"},
"G2-26": {"n":"Kodama of Eilen","f":"A kodama in an old tree at the heart of the Great Forest. Trolls are born beneath it and buried beneath it, and it forgets none of their names.","k":"Kodama","h":"1957yax"},
"G2-27": {"n":"Verdan's Leshy","f":"The antlered lord of the forest. Those who enter Verdan's woods unbidden learn, after long walking, that they've gone in circles.","k":"Leshy","h":"krit06"},
"G2-28": {"n":"Rampart Root Colossus","f":"A colossus lying rooted beneath Sawtooth Pass. Woodcutters, not knowing it was a beast, set axes to it, then laid those axes down.","k":"Root Colossus","h":"1wpnfdm"},
"G2-30": {"n":"Thornback Hedgehog","f":"A hedgehog in the brush at Sylvaniel's gate. It has lain curled in the same spot since the Covenant was first sworn.","k":"Hedgehog","h":"ahjw0u"},
"G2-31": {"n":"Drien's Green Man","f":"Memories held by Drien, the great forest spirit, took form in leaf and vine. Forgotten flowers bloom again in his wake.","k":"Green Man","h":"673k75"},
"G2-32": {"n":"Primeval Great Tree","f":"A tree that grew with the world's first forest on the Primeval Range. In its shade, time slows.","k":"Treant","h":"ftv59z"},
"G2-33": {"n":"First Tree's Dryad","f":"A dryad who stepped from the First Tree, the gate to Silvaron. Beside her, a different time still flows.","k":"Dryad","h":"12d5ry9"},
"G2-34": {"n":"Verdan's Antler Knight","f":"A stag whose antlers grew from a branch fallen from Verdan's. Seeing new leaves bud at their tips each year, the trolls named him knight.","k":"Antlered Deer","h":"e2yo4z"},
"G2-35": {"n":"Elder Tree Council","f":"A council of centuries-old trees seated in a ring. Seasons turn several times per verdict.","k":"Treant","h":"1eg2a98"},
"G2-36": {"n":"Eilen's Mycelium Heart","f":"Where the mycelium beneath the Great Forest gathers and beats. While this heart beats, the forest regrows again and again.","k":"Mushroomfolk","h":"121zafq"},
"G2-41": {"n":"Stick-Bug Javelineer","f":"It hurls spears snapped from old-tree branches. A missed spear takes root where it lands.","k":"Stick Insect","h":"mwp720"},
"G2-42": {"n":"Venom-Thorn Wasps","f":"A wasp swarm nesting deep in the Thornwood. Even trolls go around that nest.","k":"Wasp","h":"ruk93h"},
"G2-43": {"n":"Lightning Wrathwood","f":"An old tree half-burned by lightning awoke. Since then it smashes anything that smells of fire.","k":"Treant","h":"1ex8kqp"},
"G3-01": {"n":"Lagoon Novice Maiden","f":"A maiden learning her first song in the Selenea lagoon. Her voice still trembles, and the water sings the tremble back.","k":"Tree Frog","h":"uj7ikt"},
"G3-02": {"n":"Droplet Undine","f":"A tiny undine leapt from the spring. It rests a moment in a maiden's palm, then returns to the water.","k":"Undine","h":"18n8iyk"},
"G3-03": {"n":"Lagoon Dolphin Calf","f":"It sneaks past the elders to the open sea. It always comes back with something shiny in its mouth.","k":"Dolphin","h":"jfyho2"},
"G3-04": {"n":"Pearl Oyster Sentry","f":"A great oyster at the lagoon mouth. It never leaves, even at ebb tide. It has no legs to leave with.","k":"Pearl Oyster","h":"mvt1gz"},
"G3-06": {"n":"Ripple Seahorse","f":"It rides the ripples carrying news of Selenea. Its tail reaches lands far along the sea roads.","k":"Seahorse","h":"11i0kwz"},
"G3-07": {"n":"Harpoon Otter","f":"It weaves through coral hurling harpoons. Using the ones the maidens threw away, it now throws better than they do.","k":"Sea Otter","h":"14ialhg"},
"G3-08": {"n":"Echo of the Waves","f":"Marencia's song, sung by the maidens, circled the lagoon and took form. Wounds its ripples touch close without a sound.","k":"Echo","h":"t4tm9g"},
"G3-09": {"n":"Selenea Naga Guard","f":"A naga coiled beneath the bridges of the temple city on the lagoon. Its water-soaked spear is always cold.","k":"Naga","h":"tv7r32"},
"G3-10": {"n":"Young Selkie","f":"A young selkie who can't yet shed its sealskin alone. Each dawn the maidens pretend not to see it hung on the rocks.","k":"Selkie","h":"1smbb87"},
"G3-11": {"n":"Tide Seer Octopus","f":"With eight arms it marks every tide at once to read tomorrow. When it spurts ink, no boat sails that day.","k":"Octopus","h":"lneytv"},
"G3-12": {"n":"Coralback Turtle","f":"A sea turtle with coral growing on its shell. Where it cracks, harder coral covers it the next year.","k":"Sea Turtle","h":"1eu6tp7"},
"G3-14": {"n":"Tide Shark Warrior","f":"A sharkfolk warrior who surges like the flood and recedes like the ebb. The moment foes give chase, it floods again.","k":"Sharkfolk","h":"15me1dn"},
"G3-15": {"n":"Spirit of Nelia","f":"A small stream split from the great water spirit. It laughs or rages depending on the vessel it fills.","k":"Undine","h":"ssciw7"},
"G3-16": {"n":"Seahorse Royal Guard","f":"A great seahorse at the high maiden's side. Tail wound around coral, it yields not an inch until the song ends.","k":"Seahorse","h":"2kgi65"},
"G3-17": {"n":"Lagoon Healer Dugong","f":"A dugong of the lagoon's warm waters. Carry the wounded one lap on its back, and even the dying catch their breath.","k":"Dugong","h":"1y4pksx"},
"G3-18": {"n":"Coral Waterspout","f":"The lagoon's reef woke as a spirit. Raise a branch and the sea rises with it; when it falls, foes are swept away too.","k":"Coral Spirit","h":"1yytv9e"},
"G3-19": {"n":"Selenea High Maiden","f":"Leader of the Wellspring Maidens. When she begins to sing, every ripple in the lagoon lies down one way.","k":"White Whale","h":"1r7sycn"},
"G3-24": {"n":"Whirlpool Kelpie","f":"A water horse that sets the water spinning with one toss of its mane. Whoever mounts it is dragged to the bottom.","k":"Kelpie","h":"38izgh"},
"G3-27": {"n":"Trench Horseshoe Crab","f":"It guards the path Urboa climbs at the mouth of the Talakus Trench. It looked like this before the giants lay down.","k":"Horseshoe Crab","h":"1791ddm"},
"G3-28": {"n":"Lagoon Lullaby","f":"A verse of the song that keeps Talakus asleep took form in the lagoon. Where it passes, even the dead quietly return to sea.","k":"Lullaby","h":"1q4r80c"},
"G3-29": {"n":"Avatar of Nelia","f":"The formless great water spirit borrowed a shape for a moment. That shape differs for each who sees it.","k":"Undine","h":"1b2x7ek"},
"G3-32": {"n":"Deep Oarfish King","f":"An oarfish enthroned in the dark of the deep. The day it rises to the surface, the whole sea holds its breath.","k":"Oarfish","h":"jz0e6x"},
"G3-33": {"n":"Abyssal Kraken","f":"The faster Talakus's pulse, the higher it climbs from the trench. When merfolk see its tentacles, they sing one verse longer.","k":"Kraken","h":"12k8jy3"},
"G3-34": {"n":"Marencia's King Crab","f":"A king crab that raised its claws in oath before Marencia. The oath is remembered as long as the sea; the claws are harder still.","k":"King Crab","h":"16ztt8l"},
"G3-36": {"n":"Wellspring High Tide","f":"The flood answered the Wellspring Maidens' unbroken song and took form. The spring it dwells in never dries, even in drought.","k":"Tide Spirit","h":"1hqwixm"},
"G3-41": {"n":"Surge Charge Orca","f":"An orca that rides the current straight into enemy lines. Helpless on land, but the fight ends before then.","k":"Orca","h":"mqddrl"},
"G3-42": {"n":"Tsunami Sea Serpent","f":"A sea serpent riding the tsunami. In its wake lie only wet sand and scattered shields.","k":"Sea Serpent","h":"p7wxrz"},
"GN-B3-1": {"n":"Lightning Needle","t":"2 enemy units with the lowest remaining HP: HP −2 −1C.","f":"Voltarium's copper needles find the weakest pulse. One stitch, and the one holding on collapses.","b":"{Foe low HP 2} ♥−2 −1C","h":"1tc61jy"},
"GN-B3-2": {"n":"Thunderroar Barrage","t":"Enemy front unit: HP −4. All enemy units: HP −1 −1C.","f":"The plateau's capacitor towers discharge at once. The bolt pierces the front and spreads through the ground to the rear.","b":"{Foe front 1} ♥−4|{All foes} ♥−1 −1C","h":"dzpktn"},
"HA1-1": {"n":"Pickpocket","t":"Swap the leftmost card of your Hand with the leftmost card of the enemy's Hand, then draw 1 card.","f":"In Noctar's market, beware even the hand you shake. What it gives and what it takes are never the same.","b":"{Hand} Swap the leftmost cards|Draw 1 card","h":"18krgs2"},
"HA1-2": {"n":"Fingertip Curse","t":"The first unit in the enemy's Hand: [Fear 3]. Triggers at the start of its first battle once it enters the Field.","f":"Just a light brush of the fingertip. After that, a soldier in the enemy camp never stopped coughing.","b":"{Foe Hand} First unit [Fear 3]|Triggers on entering the Field","h":"1p5he7x"},
"HA1-3": {"n":"Curse Contagion","t":"The front 2 units in the enemy's Hand: [Plague 2]. Triggers at the start of the first battle once on the Field, and spreads [Plague 1] to adjacent units.","f":"A curse starts with one and spreads through the whole barracks. Even the blades of those yet to take the field grow heavy.","b":"{Foe Hand} Front 2 units [Plague 2]|Triggers on entering the Field","h":"2vxc2k"},
"HA3-1": {"n":"Covering Retreat","t":"The allied front unit falls back to the rear (retreat). Enemy front 2 units: ATK −2.","f":"While the front line falls back, arrows from the rear bind the foe's arms. The wind pushes the retreating at their backs.","b":"{Ally front 1} retreat to rear|{Foe front 2} ⚔−2","h":"14vznug"},
"HA3-2": {"n":"Scouting","t":"The first unit in the enemy hand: ATK −2 (for the whole match). Curseproof ATK is not reduced. Draw 1 card (no Life cost).","f":"News a wind scout brought back from the enemy barracks. The arms of the first foe to step out are bound in advance.","b":"{Foe hand} first unit ⚔−2 (whole match)|{Self} draw 1","h":"1tpuak1"},
"HB1-1": {"n":"Magazine Raid","t":"Pay 2 Life; burn 1 random card from the opponent's Hand to the Pyre.","f":"At midnight a few goblins slipped into the enemy magazine. Few came back, but the enemy's night was shorter.","b":"{Cost} Life 2|{Foe Hand} burn 1 random","h":"170j7ou"},
"HB3-1": {"n":"Foresight","t":"Draw 1 card (no Life cost). Put the leftmost card in your Hand on the bottom of your Deck.","f":"The gnome art of reading the air's tremor before lightning. They move already knowing the next move.","b":"Draw 1 card|Leftmost card → Deck bottom","h":"jqjhwn"},
"I2-2": {"n":"Fang Berserker Axe","f":"The double-bladed axe of the Rockfang berserkers. Forsake defense; stake all on one blow.","h":"lrrdwa"},
"I2-3": {"n":"Shadow Throwing Dagger","f":"A dagger Noctar's assassins hide up their sleeves. Thrown the moment it is equipped.","h":"hie98i"},
"I3-2": {"n":"Elad Tower Shield","f":"A tower shield of Dawnhold's gate knights. No curse can make the hand that bears it lower it.","h":"5itqm6"},
"I3-3": {"n":"Sylvaniel Longbow","f":"A warden's longbow. Shoot from afar, fall back, take no counter.","h":"q6xhf"},
"IA1-1": {"n":"Blood Oath Charm","f":"A charm bearing a name written in one's own blood. It grants power equal to the price.","h":"kr3n1g"},
"IA1-2": {"n":"Obsidian Dagger","f":"An obsidian dagger of Noctar. Its cuts never close, bleeding all battle long.","h":"qoy1j5"},
"IA1-3": {"n":"Curse Doll","f":"A doll stuffed with the foe's hair. Each needle draws a scream.","h":"1pn0667"},
"IA1-4": {"n":"Abyssal Mask","f":"A mask that erases your face the moment you wear it. The blood of those you cut redraws it.","h":"1h2act9"},
"IA1-5": {"n":"Original Contract","f":"The original of a contract made with Morkas. Each time its owner pays in blood, the signer's blade grows heavier.","h":"ycc5ws"},
"IA2-1": {"n":"Seized Obsidian Blade","f":"An obsidian blade an inquisitor took from a Fiend. Borrowed only until the purification rite ends — until then, its cuts do not heal.","h":"14k8amd"},
"IA2-2": {"n":"Silver Shield","f":"A silver shield that reflects light.","h":"z6dl1x"},
"IA2-5": {"n":"Solante's Holy Sword","f":"The holy sword the sun god Solante granted her first knight.","h":"1txc3ir"},
"IA3-3": {"n":"Guild Cloak","f":"A wind-wrapped cloak of the Storm Tower Guild. Arrows lose their way in its folds.","h":"1bf32c1"},
"IA3-4": {"n":"Whirlwind Quiver","f":"Wind blows each time an arrow is drawn. Riding it, the arrow finds armor gaps on its own.","h":"1ys6vr9"},
"IA3-5": {"n":"Belumir's Longbow","f":"The longbow of Belumir, the star-reading god. It shoots from beyond reach; when the arrow lands, the shooter is long gone.","h":"2hxree"},
"IA3-6": {"n":"Thunderfletch Arrow","f":"Arrows fletched with lightning gathered atop the Storm Tower. Lightning flies with every shot.","h":"1bw0nlx"},
"IB1-1": {"n":"Musket Stock","f":"The stock Fortan gunners swing when out of bullets. It hurts for a long time.","h":"7gmtj8"},
"IB1-2": {"n":"Ember Bandolier","f":"Small powder kegs worn round the waist. Light the wick and throw.","h":"46gk9v"},
"IB1-3": {"n":"Blunderbuss","f":"Fortan's scattergun with a trumpet-flared muzzle. It sprays one shot every turn.","h":"1nbdh5g"},
"IB1-4": {"n":"Gunner's Spyglass","f":"A spyglass by a Coghaven lensmaker. Hit the weak spot, and only strength enough to stand remains.","h":"lj60oz"},
"IB1-5": {"n":"Dormak's Flame Cannon","f":"A hand cannon loaded with a shard of the giant Dormak's Heartfire. Fire from afar and fall back; each shot only scorches the ground.","h":"89wr0x"},
"IB2-1": {"n":"Rivet Rune","f":"A rune shaped like the rivets joining golem plates. Once driven in, it never comes out.","h":"f9vf7s"},
"IB2-2": {"n":"Steel Plating","f":"Standard plating of the Durkheim workshops. Heavy, but sure.","h":"jl0ppa"},
"IB2-4": {"n":"Automaton Heart","f":"An automaton's power core. Its gears take the first blow.","h":"b5tu8x"},
"IB2-5": {"n":"Iron Shield","f":"A shield made from a golem's palm.","h":"1xgi8am"},
"IB2-6": {"n":"Golem Core","f":"A core taken from a giant golem. Inscribe it on your body and become a walking fortress.","h":"1mbwbuv"},
"IB3-1": {"n":"Copper Coil","f":"A copper coil worn on the wrist. Lightning called by that hand comes one strand thicker.","h":"59vuo5"},
"IB3-2": {"n":"Capacitor Gauntlets","f":"Fists glow once charged. Whether they charge is the day's luck.","h":"3cpkie"},
"IB3-3": {"n":"Lightning Rod Staff","f":"A staff tipped with a lightning rod. Gathered lightning sparks off on its own.","h":"1bl7nvk"},
"IB3-4": {"n":"Lightning Jar","f":"A glass jar holding lightning. It shines brightest the moment it breaks.","h":"rw8d5b"},
"IB3-5": {"n":"Academy Codex","f":"The Voltarium Academy's thick codex. One line of formula calls one more fork of lightning.","h":"jic7ix"},
"IG1-1": {"n":"Hunter's Claw","f":"The claw of a first kill, sewn to the back of the hand.","h":"1t8mx8j"},
"IG1-3": {"n":"Rage Tattoo","f":"A tattoo that glows red when blood boils. Defense is forgotten.","h":"1hblkn4"},
"IG1-4": {"n":"Rock Totem","f":"A small rock totem shamans carry on their backs. Curses are cast from afar, beyond reach of a returning fist.","h":"shuar"},
"IG1-6": {"n":"Fang War Axe","f":"A chieftain's war axe. One swing cleaves the one in front and the one behind.","h":"1e98wer"},
"IG2-1": {"n":"Thorn Tattoo","f":"A tattoo shaped like vine thorns. The striker bleeds first.","h":"19qp762"},
"IG2-2": {"n":"Bark Rune","f":"A rune modeled on old-tree bark. It thickens with the years.","h":"8j61v9"},
"IG2-3": {"n":"Moss Charm","f":"A charm woven of moss from ancient stone.","h":"k0ieab"},
"IG2-5": {"n":"Seed of Life","f":"A seed planted beside the heart. The body never withers.","h":"7e58tq"},
"IG2-6": {"n":"Verdan's Root","f":"Roots of Verdan, the forest dragon, grow along the veins. They worm into armor gaps and pry them open.","h":"sch8z0"},
"IG3-1": {"n":"Shell Charm","f":"A charm made from the first shell the waves washed up.","h":"gkwrbz"},
"IG3-2": {"n":"Spring Water Flask","f":"A flask blessed by a spring maiden. Drink, and wounds close.","h":"y20n21"},
"IG3-3": {"n":"Coral Dagger","f":"A dagger carved from red coral. Thrown, it bends like a current.","h":"1g3evf2"},
"IG3-4": {"n":"Pearl Sigil","f":"A sigil set with a deep-sea pearl. Worn on the chest, the sea breathes into you.","h":"1cua12l"},
"IG3-5": {"n":"Droplet Orb","f":"An orb sealing a single drop. Water seeps through any crack.","h":"138n00x"},
"IG3-6": {"n":"Lagoon Scale","f":"A blue scale dredged from the Selenea lagoon floor. With luck, blades slip off it.","h":"17z32j7"},
"IG3-8": {"n":"Trident of Tides","f":"A trident that calls flood and ebb.","h":"jod7vt"},
"IR-A1": {"n":"Noctar Blood Mask","f":"The mask of the Abyss Pact's executioners. Its wearer breathes in the blood that flows from the wounds they cut.","h":"15sn8vn"},
"IR-A2": {"n":"Solante's Oath Shield","f":"A shield given to Elad's knights the day they complete their oath. While the oath is kept, the first blade slides off its light.","h":"n7s8vi"},
"IR-A3": {"n":"Starscript Arrow","f":"Needle Spire archers carved the star letters Isak deciphered into the shafts. In flight, the wind shifts to follow the target.","h":"1qhphj3"},
"IR-B1": {"n":"Marksman's Musket","f":"A gun given only to one who fired a hundred shots and hit a hundred in Fortan's artillery. Its stock bears a notch for every hit.","h":"zlug4e"},
"IR-B2": {"n":"Adamant Plating","f":"Grey metal from a sleeping giant's hardened bones, beaten thin in Durkheim. Calling it unbreakable is no exaggeration.","h":"14rhl55"},
"IR-B3": {"n":"Copper Lightning Rod","f":"A staff cut from a Voltarium tower's tip. Lightning falls where it points, not on the hand that holds it.","h":"p7f36c"},
"IR-G1": {"n":"Ashmane Tattoo","f":"A tattoo only those who watched Karno Ashmane duel may wear. From that day, the blade finds vital spots.","h":"1ip46hv"},
"IR-G2": {"n":"First Tree's Bark","f":"Bark shed by Sylvaniel's First Tree itself. Every blade that cuts it comes back as a thorn.","h":"5qtvyb"},
"IR-G3": {"n":"Nelia's Droplet","f":"A drop Nelia, great water spirit, let fall into Selenea's spring. It cleanses its vessel's wounds first.","h":"83tquu"},
"M2-1": {"n":"Fang Tattoo","f":"The fang tattoo the Rockfang tribe inks on the forepaw after a first hunt. This paw tears armor first.","h":"1tmi9r4"},
"M3-1": {"n":"Golem Rune","f":"A rune Durkheim runesmiths carve into golem hearts. No curse can diminish the body that bears it.","h":"1g22t9j"},
"M4-1": {"n":"Treant's Rings","f":"A thousand-year treant's rings, etched on the body. They thicken a layer each year.","h":"v1xftb"},
"MA-01": {"n":"Blade of Dread","t":"The enemy's front 2 units: [Fear 3].","f":"The blade cuts no flesh. Whoever its shadow brushes finds their sword hand trembling the next morning.","b":"{Foe front 2} [Fear 3]","h":"nd6ezj"},
"MA-02": {"n":"Solante's Blessing","t":"Allied front unit gains [Barrier]. That unit: DEF −2.","f":"The Mother of Dawn shelters the one who leads. The blessed shed their armor and trust only the light.","b":"{Ally front 1} [Barrier] ⛨−2","h":"11nix3l"},
"MA-03": {"n":"Enfeeble","t":"Enemy front unit: ATK −5.","f":"The first defensive spell learned at the Needle Spire. Strength drains from the foe's arms like wind.","b":"{Foe front 1} ⚔−5","h":"r3hiui"},
"MA-04": {"n":"Blood Resonance","t":"1 enemy unit with the highest ATK: HP −(Offerings paid this turn + 2).","f":"Spilled blood never vanishes. It seeps down into the abyss, echoing, then bursts out all at once on the final spell.","b":"{Foe top ATK 1} ♥− Offerings +2","h":"1apodnb"},
"MA-05": {"n":"Scale of Blood","t":"[Offering 3] Destroy 1 enemy unit with the highest ATK.","f":"One sets one's own blood on a pan of Morkas's scale. The heaviest on the other side is carried off.","b":"{Offering} Life 3|{Foe top ATK 1} Destroy","h":"mue1qv"},
"MA-07": {"n":"Hit and Run","t":"Allied front 2 units: ATK +2. The front unit falls back to the rear (retreat) and gains [Ranged] this turn.","f":"Shoot, fall back, shoot again. High Elf archers never linger within blade reach.","b":"{Ally front 2} ⚔+2|{Ally front 1} retreat to rear [Ranged]","h":"12cq9ta"},
"MA-08": {"n":"Oath Binding","t":"Allied front 2 units: HP +2 +1C. Those 2 units gain [Curseproof].","f":"The oath, hardened like iron, is carved into the body. No curse seeps past a hardened oath.","b":"{Ally front 2} ♥+2 +1C|{Ally front 2} [Curseproof]","h":"qnhs0m"},
"MA-09": {"n":"Hellfire","t":"1 enemy unit with the highest DEF: its DEF D becomes −D this turn, and HP −D. The thicker the armor, the hotter it burns.","f":"Noctar's hellfire burns armor for fuel. The thicker the iron, the longer and hotter it burns, never going out.","b":"{Foe top ⛨ 1} ⛨ D → −D · ♥−D","h":"6fubd2"},
"MA-10": {"n":"Martyr's Vow","t":"This turn, whenever an allied unit is defeated, the allied units on both sides of it gain [Barrier].","f":"A sworn knight, falling, passes a last light to the brother beside him. That light takes the next blade in his place.","b":"{Allies} each time one falls|Both neighbors [Barrier]","h":"12j1tgq"},
"MA-11": {"n":"Finishing Arrow","t":"The 2 enemy units with the lowest remaining HP: HP −3.","f":"Picking out the staggering foe is part of an archer's eye. The last shot always finds the weakest spot.","b":"{Foe lowest HP 2} ♥−3","h":"xhg53"},
"MA-14": {"n":"Dawn Unleashed","t":"Release all stored [Dawnlight] plus the amount your Life trails the opponent's, reducing HP by that much starting from the enemy unit with the highest ATK. After a defeat, the rest goes to the next unit; anything still left returns to your Life.","f":"Light stored all night tears the east open at once. The sharpest blades are blinded first, and the leftover light covers the wounds of the weary.","b":"[Dawnlight] + Life gap → {Foes by highest ⚔} ♥−|Leftover: your Life +","h":"fm0jvy"},
"MA-16": {"n":"Blood Covenant","t":"[Offering 3] All allies ATK +3, [Lifesteal].","f":"All shared a single cup of blood. That night, Noctar's army lost its fear.","b":"{Offering} Life 3|{All allies} ⚔+3 [Lifesteal]","h":"1kkrmkr"},
"MB-01": {"n":"Grapeshot","t":"1 enemy unit: HP −2 −1C×2.","f":"A whole sack of iron balls went into the cannon. Not rain but iron poured across the field.","b":"{Foe 1} ♥−2 −1C×2","h":"7uhl13"},
"MB-02": {"n":"Rivet Reinforcement","t":"2 allied units: HP +2.","f":"A fresh rivet in every loose seam. Dwarves never throw away what can be fixed.","b":"{Ally 2} ♥+2","h":"17ws776"},
"MB-03": {"n":"Capacitor Release","t":"Enemy front unit: HP −1 −1C×3.","f":"Bottled lightning, let loose at once. It was as angry as it was long confined.","b":"{Foe front 1} ♥−1 −1C×3","h":"bfdgi3"},
"MB-04": {"n":"Fuse","t":"Enemy front unit: HP −1, Burn 3.","f":"A lit wick crawls along the ground to the foe's feet. The blast comes much later — goblins love the wait.","b":"{Foe front 1} ♥−1|Burn 3","h":"18gweaf"},
"MB-05": {"n":"Scatter Embers","t":"Enemy front 2 units: [Burn 2].","f":"Goblins throw sacks of embers instead of shells. No blast, but the next morning the enemy camp wakes to smoke.","b":"{Foe front 2} Burn 2","h":"ck0frb"},
"MB-06": {"n":"Heat-Shield Wall","t":"3 enemy units: HP −1. 3 allied units: DEF +1.","f":"Glowing iron plates rise like a wall against the heat. The approaching foe was scorched by the wall's heat first.","b":"{Foe 3} ♥−1|{Ally 3} ⛨+1","h":"14cjsws"},
"MB-07": {"n":"Overload Circuit","t":"3 allied units: ATK +1 +1C.","f":"Every safety off, the circuit flooded to its limit. If it smells burnt, it worked.","b":"{Ally 3} ⚔+1 +1C","h":"1u0gclf"},
"MB-08": {"n":"Armor Lock","t":"Your 2 front units: DEF +1, HP +1. Those 2 units gain [Curseproof].","f":"Every plate's bolts tightened to the end. Not one seam is left for a curse to creep in.","b":"{Ally front 2} ⛨+1 ♥+1|{Ally front 2} [Curseproof]","h":"83y2ok"},
"MB-11": {"n":"Targeted Strike","t":"Destroy 1 enemy unit with the highest ATK. 1 allied unit: HP −1. [Reload 2]","f":"Gnomes calculate where lightning will fall. If the math is a little off, the one beside it burns.","b":"{Foe top ATK 1} Destroy|{Ally 1} ♥−1","h":"1gxmiub"},
"MC-01": {"n":"Crouching Wolves","t":"All allied units' ATK becomes 1 this turn and can't change. All enemy units: ATK −(total ATK lost this way) (this turn).","f":"The wolf pack hides its fangs and hugs the ground. The charging foe falters, unsure where to bite.","b":"{All allies} ⚔ 1 (fixed this turn)|{All foes} ⚔ −(total lost)","h":"1t1jvel"},
"MC-02": {"n":"Sharpen Blades","t":"Allied front 2 units: ATK +4.","f":"Before a bombardment, goblins whet their bayonets. They hope never to need them, yet keep the edges keen.","b":"{Ally front 2} ⚔+4","h":"1ab9yh1"},
"MC-03": {"n":"Turned Waterway","t":"Reorder enemy units from the front by highest DEF + HP total (spell slots stay put). Your front-most unit gains [Heal 1] this turn.","f":"When the waterway turns, ships drift against their will. The sturdy are pushed forward; the swift are pushed back with no time to draw.","b":"{Foes} reorder by DEF+HP|{Ally front 1} [Heal 1]","h":"1vw0a50"},
"MC-04": {"n":"Invocation","t":"Your front 2 units: HP +1 +1C. Your front-most unit gains [Purify] this turn.","f":"Maidens kneel at the water's edge in prayer. The lagoon rises quietly to bathe the wounds of those in front.","b":"{Ally front 2} ♥+1 +1C|{Ally front 1} [Purify]","h":"15hmpbf"},
"MC-05": {"n":"Hallucination","t":"The enemy's front unit hallucinates and strikes the allied unit right behind it with its own ATK.","f":"Those who breathe Noctar's mist see the comrade beside them as a Fiend. Only after the blade falls do they know the face.","b":"{Foe front 1} Hits its own ally behind with its ⚔","h":"1hn2i79"},
"MC-06": {"n":"Disarm","t":"All enemy units: ATK −1. The enemy front 2 units get a further ATK −2.","f":"The wind twists the hilt free of the hand. The nearer the front a foe stands, the farther it flies.","b":"{All foes} ⚔−1|{Foe front 2} ⚔−2 more","h":"sa55uc"},
"MC-08": {"n":"Ripple","t":"1 enemy unit: HP −2. Enemy front 2 units lose [Barrier]·[Thorns]·[Curseproof]·[Guard] and HP −2 more.","f":"A single bolt spreads like a wave. Shells of steel and spell peel away one by one at its tremor.","b":"{Foe 1} ♥−2|{Foe front 2} Strip abilities ♥−2","h":"10tm7cp"},
"MC-11": {"n":"Silence","t":"The 2 front-most enemy units' ATK becomes 0, and they take HP −3.","f":"When the forest holds its breath, all sound vanishes. Foes forget even how to raise a blade.","b":"{Foe front 2} ⚔=0 ♥−3","h":"178iq6z"},
"MC-14": {"n":"Armored Coil","t":"All enemy units take damage equal to their own DEF, and their DEF becomes 0 this turn.","f":"Countless vines coil round the foe, armor and all. Twisted-off armor sinks beneath the moss.","b":"{All foes} damage = ⛨|then ⛨ 0","h":"1l7jbqf"},
"MC-16": {"n":"Faithless Barrage","t":"All enemy units: HP −1. Enemy front 2 units: HP −3 more.","f":"Rather than pray to gods, add another fistful of powder. It is the only prayer the Titanbone know.","b":"{All foes} ♥−1|{Foe front 2} ♥−3 more","h":"1lqkfkk"},
"MG-01": {"n":"Fang Charge","t":"2 allied units: ATK +1 +1C.","f":"The orcs at the back bare their fangs. Leaping over the front line, they are the first to land.","b":"{Ally 2} ⚔+1 +1C","h":"1pmnmxp"},
"MG-03": {"n":"Sip of Spring Water","t":"Your front-most unit gains [Heal 2] this turn.","f":"A sip of Selenea's spring water. It runs down the throat and wakes the weary body again.","b":"{Ally front 1} [Heal 2]","h":"1fvbw6s"},
"MG-04": {"n":"Grudge Strike","t":"1 allied unit: ATK +(unit cards in your Pyre).","f":"With each fallen brother's name, the fist grows heavier. At the last name, it falls.","b":"{Ally 1} ⚔+(Pyre units)","h":"ui39br"},
"MG-05": {"n":"Earthquake","t":"4 enemy units: HP −1. 3 allied units: ATK +1C.","f":"The orcs stamp as one and the earth rings. The farther the foe, the more the tremor buckles its legs.","b":"{Foe 4} ♥−1|{Ally 3} ⚔+1C","h":"1odrh6u"},
"MG-08": {"n":"Root Bind","t":"3 enemy units: ATK −2 −1C×2.","f":"Roots burst from the earth and coil round ankles. Those lurking at the back are caught first.","b":"{Foe 3} ⚔−2 −1C×2","h":"1ajxt73"},
"MG-10": {"n":"Elder Tree Veil","t":"1 allied unit: DEF +1, [Thorns 1 +1C×2].","f":"An old tree lowers its branches as a veil. Hands that would tear it are pricked by thorns.","b":"{Ally 1} ⛨+1 [Thorns 1] +1C×2","h":"4rslpx"},
"MG-11": {"n":"Inverted Water Mirror","t":"Swap ATK and DEF of the first 2 enemy units (except [Curseproof] units).","f":"In the water mirror a warrior sees himself holding a shield, not a sword. The force of his swing hardens like a shell, dulling the edge.","b":"{Foe front 2} ⚔ ↔ ⛨","h":"37s9u5"},
"MG-12": {"n":"Wellspring Blessing","t":"All enemy units' Coins turn tails (Coin chance −50%; Coins already decided stay). Your front-most unit: HP +2 +1C.","f":"A spring maiden sprinkles blessed water. The foe's luck washes away and allied wounds close.","b":"{All foes} Coins tails|{Ally front 1} ♥+2 +1C","h":"1s9r8n9"},
"MG-13": {"n":"Bonebreaker","t":"Among enemy units with 0 DEF, swap the DEF and HP of the 1 unit with the highest ATK (it drops to 0 HP and is defeated).","f":"Strip the armor and only bone remains. Gorvath's fist breaks that bone like rock.","b":"{Foe 0 DEF, top ATK 1} ⛨ ↔ ♥ (defeated)","h":"16hscmv"},
"MG-14": {"n":"Weight of the Forest","t":"Total all allied units' remaining HP. Cut that much from enemy units, starting at the front, in order ATK → DEF → HP (ATK and DEF for this turn). If a unit is defeated, the rest carries to the next unit.","f":"The whole forest leans one way. The weight of enduring bodies pours down, crushing whatever stands in front, one by one.","b":"{From foe front} cut ⚔ → ⛨ → ♥|Pool = {Allies} ♥ total · rest carries on","h":"9u8k7b"},
"MG-15": {"n":"Healing Tide","t":"All allied units gain [Heal 1] this turn. All allies: HP +1.","f":"A warm flood tide washes the battlefield. When the water recedes, the fallen rise one by one.","b":"{All allies} [Heal 1] ♥+1","h":"1n1ync8"},
"MG-16": {"n":"Earth Collapse","t":"All enemy units: HP −3. All allied units: HP −2 −1C.","f":"The ground gives way entirely. The orcs laugh as they fall too. Whoever gets up first wins.","b":"{All foes} ♥−3|{All allies} ♥−2 −1C","h":"omx1t6"},
"NA1-1": {"n":"Shadow Theft","t":"Seize the enemy card in the same slot number as this spell and place it at the back of your Field. A unit fights as your unit this turn and, if it survives, returns to the back of the enemy Field when battle ends. A face-down spell activates as your spell.","f":"It grabs the shadow of what the foe set down and drags it over. What is borrowed scatters back when the fight ends.","b":"{Foe same slot} Seize card|Slot = this spell's slot · placed at your back|Units yours this turn only · returned if alive","h":"3jsrwi"},
"NA2-1": {"n":"Light of Salvation","t":"1 enemy unit — the front-most one with an ability and a lower Level than your front unit — becomes a Dawnhold Statuette (ATK 0 · DEF 2 · HP 4, no ability) this turn.","f":"Those the light settles on lay down their weapons. When they open their eyes, they stand frozen before their comrades like a little statue in Dawnhold's plaza.","b":"{Foe w/ ability, Lv below ally front 1}|→ Statuette 0/2/4","h":"qlttg8"},
"NA2-2": {"n":"Wings of Light","t":"Allied front 2 units gain [Barrier] and DEF +1.","f":"Solante's six wings enfold the two at the very front. Before a blade can land, feathers of light catch it.","b":"{Ally front 2} [Barrier] ⛨+1","h":"1qenbt0"},
"NA3-1": {"n":"Rending Wind","t":"All enemy units' DEF becomes 0 (this turn). All enemy units: HP −1.","f":"A wind that burrows only into armor joints. In its wake, steel hangs in tatters like cloth.","b":"{All foes} ⛨ to 0|{All foes} ♥−1","h":"99xy2p"},
"NA3-2": {"n":"Arrow Rain","t":"All enemy units except the front one: HP −3.","f":"Arrows fall like rain beyond the shield wall at the front. Those hiding behind fall first.","b":"{All foes behind front} ♥−3","h":"1fcmidf"},
"NA3-3": {"n":"Starlight Volley","t":"For each allied unit holding a [Bow], all enemy units lose 2 HP.","f":"The moment the bowstrings sound as one, arrows become starlight covering the sky. The more hands hold bows, the heavier the starfall.","b":"{All foes} ♥− 🏹[Bow] allies × 2","h":"177fjyh"},
"NA3-4": {"n":"The Wind's Hunt","t":"All enemy units: HP −3. All allied units: [Ranged].","f":"The hunting horn sounds atop Belumir's Needle. That day High Elf arrows ride the wind, and not one blade reaches them.","b":"{All foes} ♥−3|{All allies} [Ranged]","h":"1lvztxp"},
"NB1-1": {"n":"Armor-Piercing Shell","t":"Enemy front unit: 3 physical damage.","f":"A shell clad in layer on layer of iron. Even after punching through a shield, it rolls on a long way.","b":"{Foe front 1} 3 phys dmg","h":"mnz9r8"},
"NB1-3": {"n":"Fire Wind","t":"All enemy units: [Burn 1]. Enemy front unit: [Burn 3].","f":"When Dormak's Heartfire exhales, hot wind blows over the Fortan pass. Embers settle wherever it passes.","b":"{All foes} Burn 1|{Foe front 1} Burn 3","h":"4byp32"},
"NB2-1": {"n":"Overdrive","t":"All allied units: DEF +1. Then each allied unit gains ATK equal to its own DEF.","f":"Boiler pressure pushed past its limit. The tougher they were, the harder they charged.","b":"{All allies} ⛨+1|{All allies} ⚔ + own ⛨","h":"ysa07q"},
"NB2-2": {"n":"Shield Wall Cry","t":"Your toughest unit steps to the front ([Guard]). That unit: DEF +2.","f":"The dwarf with the thickest shield steps forward. His comrades' cry pushes at his back.","b":"{Allies} toughest 1|To front [Guard] ⛨+2","h":"17k0snr"},
"NB3-1": {"n":"Chain Lightning","t":"From the front of the enemy Line, in order: HP −2 → −1.","f":"Lightning never stops at one. It pierces the front, then seeks the next with what is left.","b":"{Foe from front} In order ♥−2→−1","h":"1k9xfia"},
"NB3-2": {"n":"Coin of Fate","t":"This turn, allied units' Coins: every + Coin lands heads, every − Coin lands tails. Allied front 2 units: ATK +1.","f":"Gnomes believe even luck can be calculated. That coin is heads before it is tossed.","b":"{Allies} All Coins favorable|{Ally front 2} ⚔+1","h":"pryb4j"},
"NG1-1": {"n":"Rage","t":"All allied units' remaining HP becomes 1, and they gain ATK equal to the HP lost (this turn).","f":"The deeper the wound, the redder an orc's eyes. Nothing is as fearsome as an orc about to fall.","b":"{All allies} ♥ to 1|⚔+ per ♥ lost","h":"1g7h2gu"},
"NG1-2": {"n":"Pack Roar","t":"From the enemy front, as many units as you have allied units: HP −(allied units × 2).","f":"The bigger the pack, the louder the howl. The roar spreads to the steppe's edge and the enemy ranks waver.","b":"{Foes from front} as many as allied units|♥− allied units×2","h":"vsffwc"},
"NG2-1": {"n":"Root Delve","t":"Each enemy unit with DEF 1 or more takes damage equal to its own DEF +1.","f":"Roots crawling underground rise through every armor gap. The unarmored they simply pass by.","b":"{All foes with DEF} damage ⛨+1","h":"1fag0ir"},
"NG2-3": {"n":"Forest Renewal","t":"2 front-most allied units gain [Regenerate 2].","f":"As shoots sprout from cut branches, the forest's wounds close. While the forest lives, they do not fall.","b":"{Ally front 2} [Regenerate 2]","h":"mtgp7x"},
"NG3-1": {"n":"Raging Waves","t":"All enemy units: HP −3.","f":"The sea rises wild and crashes ashore. The merfolk sing atop the waves.","b":"{All foes} ♥−3","h":"127wn31"},
"NG3-2": {"n":"Backflow","t":"Swap the enemy's front-most and rearmost units, then the new front-most unit: HP −2.","f":"The current suddenly runs backward. The one hiding at the back is swept out to meet the wave at the front.","b":"{Foe} swap front ↔ back|{Foe front 1} ♥−2","h":"53gvsg"},
"PI-A1": {"n":"Morkas's Counterweight","f":"A weight taken from the Silent Lord's scale. Its holder's blade grows heavier, and the scale lightens the first blow. But while held, one's own wounds never close. Such is the law of price.","h":"1uobz1d"},
"PI-A2": {"n":"Solante's Wing Feather","f":"A feather the Mother of Dawn plucked from her six wings. Its bearer's defense grows as thick as the feather, and its edge cuts like a blade, leaving wounds that never close.","h":"r0a5op"},
"PI-A3": {"n":"Belumir's Starstring","f":"A string the star-reading god twisted from starlight. The drawer's strength sets fast in that instant, and the taut string flicks away the first arrow.","h":"1x2rv43"},
"PI-B1": {"n":"Dormak's Heartfire","f":"A handful scooped from the giant's unquenched Heartfire beneath the Firecrown Range. From that day the bearer's strength is set by its blaze, and flames strike back at blades it blocks.","h":"1kb57p5"},
"PI-B2": {"n":"Sorgrim's Sinew","f":"A strand of the sleeping giant's sinew, a bare vein of the Ironframe Range, twisted and wound about the body. It has never snapped, and when it glows hot, it sets alight all it touches.","h":"16ryigv"},
"PI-B3": {"n":"Zrak's Lightning Jar","f":"The jar the great lightning spirit escaped from. Leftover lightning sparks unevenly at the fingertips; those who try to smash it get burned.","h":"j3yj5d"},
"PI-G1": {"n":"Karno's Dueling Gloves","f":"Gloves Karno Ashmane cast off at his hundredth duel. No curse shrinks the wearer's fist, and wounds close mid-fight.","h":"18d4l67"},
"PI-G2": {"n":"Drien's Seed","f":"The first seed of the great forest spirit. It grants its host an old tree's lifespan. Cut down, it regrows as tall; its branches seek the throat.","h":"xwe5wa"},
"PI-G3": {"n":"Marencia's Scale","f":"A scale the water dragon shed on the day of the pact. It keeps its bearer as they were that day; foes who see its glint lose their wits.","h":"1a40guc"},
"PN-A1-C1": {"n":"Young Vampire","f":"Once a guest handed an oath instead of a cup at a Noctar noble's feast. Now blood never dries on its fangs, but its wounds never close either.","k":"Vampire","h":"ajjoe"},
"PN-A1-C2": {"n":"Mork Gorge Shade","f":"An ownerless shadow risen from the floor of Mork Gorge. In the light it only fades from sight; it has never vanished.","k":"Shade","h":"pl2qj8"},
"PN-A1-C3": {"n":"Pact-Bound Flesh Giant","f":"A giant stitched together to swing only as hard as its contract states. How many men's worth is written on the back page.","k":"Flesh Giant","h":"1bkny2w"},
"PN-A1-E": {"n":"Veil Dealer","f":"A scarecrow that left something behind in the Abyssal Veil. Even it cannot recall what. That is why its wounds never heal.","k":"Scarecrow","h":"1h6oo5c"},
"PN-A1-R": {"n":"Shadow Pact Enforcer","f":"It carries a copy of Azra's contract. Of an oath-breaker's breaths, it leaves exactly one.","k":"Raven","h":"popbv6"},
"PN-A1-U1": {"n":"Blood-Sworn Swordsman","f":"He swore an oath by feeding his sword his blood, and rose even after death. Until the oath's price is paid, the grave will not take him.","k":"Death Knight","h":"1dbjjqw"},
"PN-A1-U2": {"n":"Morkas's Tithe Taker","f":"He never let go of his ledger, even the day he died, and so became a wraith. He still won't knock a single coin off the Silent Lord's share.","k":"Wraith","h":"1v2svwy"},
"PN-A2-C1": {"n":"Dawnhold Statuette","f":"Small statues set in every roadside niche of Dawnhold. Those washed by Solante's light with nowhere to return take this form and guard Elad.","k":"Holy Statue","h":"1n68q68"},
"PN-A2-C2": {"n":"Ophanim of Elad","f":"Two golden wheels set with eyes turn interlocked. Since taking one span of Elad's wall, they have not rolled an inch.","k":"Ophanim","h":"15h6073"},
"PN-A2-C3": {"n":"Twilight Wall Pegasus","f":"It flies above the Twilight Wall that faces the Empty Land. Whatever comes from beyond, it never folds its wings.","k":"Pegasus","h":"1ojiggi"},
"PN-A2-E": {"n":"Oathkeeper of Twilight","f":"Last oathkeeper of the ancient Order of Radiance that sealed the Grey Prison. That day's oath is not yet released.","k":"Oath Soul","h":"123phjx"},
"PN-A2-R": {"n":"Dawnlight Shield Lion","f":"It raises its mane only toward the sunrise. The first blade aimed at those beside it slides off that dawnlit mane.","k":"Dawn Lion","h":"cfv5ju"},
"PN-A2-U1": {"n":"Oath-Etched Knight","f":"The knight fell long ago; only the oath etched inside the armor remained, and rose wearing it. While the oath holds, the empty armor will not break.","k":"Oath Soul","h":"b2xyfg"},
"PN-A2-U2": {"n":"Solante's Choir","f":"A flock of larks singing each dawn to the six-winged Mother. Believing no one falls before the song ends, they rarely end it.","k":"Lark","h":"ponnk5"},
"PN-A3-C1": {"n":"Constellation Hound","f":"A hound constellation running across the night sky. Any path it runs remains in starlight, never forgotten.","k":"Constellation","h":"1pjs5ey"},
"PN-A3-C3": {"n":"Longbow Griffin Knight","f":"A griffin knighted by the Storm Tower Guild. It has no hands to draw a longbow, but one wingbeat sends a wind arrow a longbow's range.","k":"Griffin","h":"oz3a3r"},
"PN-A3-E": {"n":"Isak's First Pupil","f":"A snow leopard who first learned the bow from Isak, decipherer of the star letters. Long after the master left among the stars, it aims at the same star.","k":"Snow Leopard","h":"1f7z5z3"},
"PN-A3-R": {"n":"Starlight Archmaster","f":"He received a hem of the thousand-eyed robe. The arrows of archers beside him bend on their own into armor gaps those eyes reveal.","k":"Peacock","h":"1tg6ep4"},
"PN-A3-U1": {"n":"Starscript Owl","f":"An owl with star letters carved on every feather. Letters sent by its wingbeat scatter in no wind.","k":"Star Owl","h":"ym5xpc"},
"PN-A3-U2": {"n":"Sky Cradle Griffin","f":"It nests before the Needle Spire's top gate. Though Sirel the wind dragon plays tricks, neither gate nor nest is shaken.","k":"Griffin","h":"wazwzv"},
"PN-B1-C1": {"n":"Salamander Hatchling","f":"A baby lizard hatched in a powder-store firebox. When embers run short, Fortan loaders touch a slow match to its tail to borrow fire.","k":"Salamander","h":"whfcd6"},
"PN-B1-C3": {"n":"Bombardier Beetle","f":"A Firecrown Range beetle that sprays boiling juice from its rear. Gunners pretend not to hear it reloads faster than Fortan's batteries.","k":"Bomb Beetle","h":"1n01xyl"},
"PN-B1-E": {"n":"Beating Heartfire Shard","f":"A shard broken from Dormak's Heartfire that still beats. It quickens as Talakus's pulse quickens; Fortan doesn't ask whether that is good.","k":"Heartfire Shard","h":"xndvj4"},
"PN-B1-R": {"n":"Gunsmoke Fire Hawk","f":"A fire hawk that dives only when the gunsmoke is thickest. While it circles above the smoke, even Fortan gunners work faster.","k":"Fire Hawk","h":"1ner02d"},
"PN-B1-U1": {"n":"Furnace Hearth Spirit","f":"A fire spirit dwelling in the furnace beside a Fortan powder store. It lets not one ember into the store, yet seldom goes out itself.","k":"Hearth Spirit","h":"1gfc6w4"},
"PN-B1-U2": {"n":"Dormak's Fire Spider","f":"A spider spinning molten-stone webs between Dormak's ribs beneath the Firecrown Range. What it catches hardens before it can escape.","k":"Fire Spider","h":"1se4nyx"},
"PN-B2-C1": {"n":"Rivet-Claw Crab","f":"A crab that collects rivets from rust pools in the Ironframe Range and drives them into its shell. Hit it anywhere and it rings the same.","k":"Ironclad Crab","h":"fugwts"},
"PN-B2-C2": {"n":"Steam Digger Mole","f":"A mole that lives by eating iron veins. Its breath is hot as steam, and Durkheim miners warm frozen hands in the tunnels it leaves.","k":"Steel Mole","h":"1l4zmzt"},
"PN-B2-C3": {"n":"Ironframe Hammer Giant","f":"A colossus made only of iron from the veins of the Ironframe Range. Both arms are hammers whole, so once it blocks, it strikes on its own.","k":"Colossus","h":"y0ruqn"},
"PN-B2-E": {"n":"Golem That Saw Feros","f":"A golem that met Feros, the metal dragon, deep in the veins, and came back. Since then its body reflects like a mirror.","k":"Golem","h":"mzgtye"},
"PN-B2-R": {"n":"Sorgrim's Shield Spirit","f":"The memory of the arm the sleeping Sorgrim once raised to ward something off, condensed upon iron. In the line where it stands, shields grow a little harder.","k":"Shield Spirit","h":"1918usv"},
"PN-B2-U1": {"n":"Durkheim Shieldwright","f":"He carries only shields beaten with his own tail. Every nick on them counts a day he held the line.","k":"Irontail Beaver","h":"1sdf20i"},
"PN-B2-U2": {"n":"Vein Beetle","f":"A beetle whose shell turned to ore from gnawing the veins where Sorgrim's sinews lie bare. It neither melts nor bends, so the striker's wrist cries first.","k":"Ore Beetle","h":"1ob0tfe"},
"PN-B3-C1": {"n":"Thunder Beast Cub","f":"Picked up where lightning struck. It never discharges when it trips, so Voltarium's apprentices fight to carry it.","k":"Thunder Beast","h":"1gby8gq"},
"PN-B3-C2": {"n":"Runaway Capacitor","f":"A capacitor charged to its limit, given legs. Any more and it blows. It cannot be fixed.","k":"Capacitor","h":"l78c75"},
"PN-B3-C3": {"n":"Insulated Armor Engine","f":"A walking engine of Voltarium, layered in rubber and glass. Lightning and blade alike stop at the same depth.","k":"Thunder Engine","h":"zqfkz7"},
"PN-B3-E": {"n":"Keraun Nerve Amplifier","f":"A walking device hung on one strand of the sleeping giant's nerves. When lightning passes once, everything in line trembles.","k":"Capacitor","h":"ywsph3"},
"PN-B3-R": {"n":"Bottled Storm Caller","f":"Since Zrak fled, it refills each empty jar with a little lightning. Every jar that breaks makes allied spells stronger.","k":"Genie","h":"1tlq0ad"},
"PN-B3-U1": {"n":"Lodestone Wraith","f":"Iron struck countless times atop a lightning tower became a spirit. Nearby nails and keys drift toward it, and allied spells bend its way a little harder.","k":"Magnet Spirit","h":"ox8k6p"},
"PN-B3-U2": {"n":"Plateau Thunderbird","f":"Lands only where Keraun's nerves run. Lightning strikes every rock it perched on, so surveyors follow it, driving stakes.","k":"Thunderbird","h":"ocj7zg"},
"PN-G1-C1": {"n":"Rockfang Runt","f":"Youngest of the tribe, but its fangs match its elders'. Whatever anyone says, the fangs don't shrink.","k":"Sabertooth","h":"hwf6rq"},
"PN-G1-C3": {"n":"Boulder Hulk","f":"A rock spirit of dozens of boulders fused as one. The day the biggest thing in Garun's great camp wasn't an orc, the orcs felt a little hurt.","k":"Rock Spirit","h":"ezjgn9"},
"PN-G1-E": {"n":"Throne Peak Mammoth","f":"A mammoth of the snowy passes on Gorvath's back. When it carries an orc down Throne Peak, an avalanche follows.","k":"Mammoth","h":"1q1qdh6"},
"PN-G1-R": {"n":"Karno's Pursuer","f":"It visits every arena Karno Ashmane passed through and challenges whoever won there.","k":"Bighorn","h":"18hkytl"},
"PN-G1-U2": {"n":"Bearskin Berserker","f":"It fought wearing the hide of a bear slain barehanded, until one day the hide wouldn't come off. Since then, nothing breaks its fury.","k":"Werebear","h":"19ir590"},
"PN-G2-C1": {"n":"Mossy Sapling","f":"Cut it, and next day it stands just as tall. Trolls call that stubbornness.","k":"Treant","h":"1jrp0h9"},
"PN-G2-C2": {"n":"Bramble Vine Fiend","f":"Brambles crawling along the Rusted Marsh's edge. Try to pull them, and the roots sink a hand deeper.","k":"Vine Horror","h":"4euc13"},
"PN-G2-C3": {"n":"Marsh Hydra","f":"A many-headed serpent of the marsh where the Rustwater River reaches. Cut one head, and two grow back reeking of rust.","k":"Marsh Hydra","h":"slk0ud"},
"PN-G2-E": {"n":"Primeval Mosshorn Stag","f":"A stag from the world's first forest. It slept a thousand years in Verdan's antler-shade, and a forest grew on its antlers.","k":"Antlered Deer","h":"1rpjbhg"},
"PN-G2-R": {"n":"Drien's Moss Giant","f":"It rose where Drien, the great forest spirit, passed. Under the moss lie thorns; under the thorns, the forest's memory.","k":"Moss Giant","h":"1615zzg"},
"PN-G2-U1": {"n":"Tendril Pixie","f":"Tendrils wrapped round its body bind wounds at once. Only its thorn-shooting hand is kept free.","k":"Pixie","h":"1o1y6dt"},
"PN-G2-U2": {"n":"Mycelium Rootkeeper","f":"Mushroomfolk threading mycelium among the great-tree city's roots. Thanks to them, Sylvaniel's roots share news.","k":"Mushroomfolk","h":"1mdgio"},
"PN-G3-C1": {"n":"Living Water Mirror","f":"The stillest water of the Selenea lagoon rose and became a mirror. Its reflection does not shrink when wounded.","k":"Water Mirror","h":"ik57g0"},
"PN-G3-C3": {"n":"Trench Songwhale","f":"A whale in the Talakus Trench that sings only for Marencia. One song takes a season to finish.","k":"Whale","h":"7oy389"},
"PN-G3-E": {"n":"Urboa Scale Knight","f":"Armor made from scales shed by Urboa, the great serpent of the deep. No spear has ever thinned them.","k":"Naga","h":"uexsbv"},
"PN-G3-R": {"n":"Nelia's Vessel Maiden","f":"She bears the vessel that holds the water spirit Nelia. The deep song spilling from it wraps those beside her and dulls blades.","k":"Nereid","h":"1gega5l"},
"PN-G3-U2": {"n":"Anglerfish of Talakus","f":"At the trench floor it blinks its lantern to the giant's pulse. While the pulse lasts, its light never fails.","k":"Anglerfish","h":"87hckn"},
"PS-A1-1": {"n":"Soul Extortion","t":"2 enemy units with the highest ATK: ATK −3 (not below 0). Allied front unit: ATK + the total reduced.","f":"Noctar's contracts always have one more line: what is taken belongs to the taker.","b":"{Foe top ATK 2} ⚔−3|{Ally front 1} ⚔+ amount reduced","h":"e57vwh"},
"PS-A1-2": {"n":"Plague Shackles","t":"1 enemy unit with the highest ATK: ATK −2. It gets [Plague 2].","f":"The rusted shackle binds not the ankle but the breath. Even when the chain comes loose, the cough passes to the next one.","b":"{Foe top ATK 1} ⚔−2 [Plague 2]","h":"2nriyh"},
"PS-A2-1": {"n":"Stigmata","t":"Allied front 2 units gain [Aegis 1]. This turn, gain [Dawnlight] equal to the HP your allied units lose.","f":"Celestial blood does not soak into the earth. Light pools in every wound, and bursts out all at once when dawn comes.","b":"{Ally front 2} [Aegis 1]|Allied ♥ lost → [Dawnlight]","h":"ida4y4"},
"PS-A2-2": {"n":"Light of Order","t":"Every enemy unit's ATK becomes equal to the lowest ATK among them.","f":"Under Solante's order, nothing overflows or falls short. Even raging blades lie down evenly in that light.","b":"{All foes} ⚔ = lowest foe ⚔","h":"u2t3sb"},
"PS-A3-1": {"n":"Rotation","t":"The enemy front unit's ATK moves to DEF, DEF to HP, and HP to ATK.","f":"The stars turn, and a star that turns never returns to its place. The first letter Isak read was that one revolution.","b":"{Foe front 1} rotate ⚔→⛨→♥→⚔","h":"jam1d1"},
"PS-A3-2": {"n":"Star Mimicry","t":"Among the ATK · DEF · HP of the allied front 2 units, any lower than those of the enemy unit with the highest ATK (1 unit) become that value.","f":"High Elves write what they see in star letters, and carry what they write into their own bodies.","b":"{Ally front 2} ⚔⛨♥ lower ones = {Foe top ATK 1}","h":"g0xfdk"},
"PS-B1-1": {"n":"Backfire","t":"1 enemy unit with the highest ATK takes physical damage equal to its own ATK (reduced by its own DEF).","f":"Fortan powder always spills over a little. The spilled fire bursts in the hand that swung hardest.","b":"{Highest-ATK foe 1} own ⚔ as phys dmg","h":"xvi3mc"},
"PS-B1-2": {"n":"Burning Resolve","t":"2 allied units: ATK +3. Their ATK can't be reduced this turn.","f":"Once a fuse is lit, there's no going back. Goblins call that resolve.","b":"{Ally 2} ⚔+3 · ⚔ can't drop this turn","h":"1a4v7tc"},
"PS-B2-1": {"n":"Steel Oath","t":"Your 2 front units: DEF +1, HP +1. Those 2 units' DEF and HP can't be reduced this turn (except by damage).","f":"The oath of the Durkheim workshops is short: \"We do not rust.\"","b":"{Ally front 2} ⛨+1 ♥+1|{Ally front 2} ⛨ ♥ can't drop this turn","h":"8haqog"},
"PS-B2-2": {"n":"Quench","t":"Your front unit's HP becomes ATK, DEF becomes HP, and ATK becomes DEF.","f":"Beat hot iron and quench it, and soft spots harden while hard ones become an edge. Golems too.","b":"{Ally front 1} Cycle ⚔→⛨→♥→⚔","h":"1dve9h3"},
"PS-B3-1": {"n":"Amplifier Circuit","t":"Allied front 2 units gain [Amplify 1] this turn.","f":"A Voltarium gnome plugged copper circuits into two soldiers' backs. The sky's lightning falls thicker through them.","b":"{Ally front 2} [Amplify 1]","h":"1ovqzqk"},
"PS-B3-2": {"n":"Electrode Swap","t":"Swap the ATK of 1 allied unit with the lowest ATK and 1 enemy unit with the highest ATK.","f":"Swap anode and cathode, and the flow runs backward. A gnome need only choose the direction.","b":"{Ally low ATK 1} ⚔ ↔ {Foe top ATK 1} ⚔","h":"rkr3eo"},
"PS-G1-1": {"n":"Victory Cry","t":"At the end of battle, opponent's Life −(surviving allied units).","f":"When the fight ends, those still standing howl together. At the sound, the enemy camp crumbles step by step.","b":"{Foe Life} −(allies alive at battle end)","h":"7vo6vt"},
"PS-G1-2": {"n":"Pack Fury","t":"All allied units' ATK becomes equal to the highest ATK among allies.","f":"When the chieftain howls, the whole pack grows as fierce as the chieftain.","b":"{All allies} ⚔ = highest ally ⚔","h":"3b5jx4"},
"PS-G2-1": {"n":"Growth Rings","t":"1 allied unit: HP +2, DEF +1. Its HP cannot decrease this turn (except from damage).","f":"An old tree adds a ring for every year endured. A ring once added never comes off.","b":"{Ally 1} ♥+2 ⛨+1|♥ can't drop this turn","h":"48yocc"},
"PS-G2-2": {"n":"Taking Root","t":"2 front-most allied units move all their ATK to DEF (ATK 0, DEF + amount moved).","f":"A troll stops fighting and buries its feet in the earth. There it holds, becoming a tree.","b":"{Ally front 2} move all ⚔ to ⛨","h":"l8d2ww"},
"PS-G3-1": {"n":"Mirror of Water","t":"Swap ATK and HP of every enemy unit whose ATK is higher than its HP.","f":"What Nelia's water reflects stands inverted. The blade becomes the body; the body becomes the blade.","b":"{All foes} if ⚔ > ♥, ⚔ ↔ ♥","h":"1owiq2a"},
"PS-G3-2": {"n":"Ebb","t":"All enemy units: ATK −2. Enemy units' ATK cannot rise further this turn.","f":"When the water recedes, the momentum of those riding the waves recedes too. It won't return until the next tide.","b":"{All foes} ⚔−2 · ⚔ can't rise this turn","h":"1xixzp"},
"RA1-1": {"n":"Final Contract","t":"Destroy all units on the Field on both sides.","f":"The last deal struck with Morkas. The price is every life on the Field, and the scale settles perfectly level.","b":"{All, both sides} Destroy","h":"10vxcq0"},
"RA2-1": {"n":"Day of Judgment","t":"Allied front unit gains [Barrier]. All units on both sides: HP −6. [Reload 2]","f":"On the day the sky outshines noon, the light takes no sides. Only the one at the very front remains beneath the wings.","b":"{Ally front 1} [Barrier]|{All units, both sides} ♥−6","h":"t5umre"},
"RA3-1": {"n":"Eye of the Storm","t":"All enemy units neither attack nor counter this turn. All allied units: HP −2. [Reload 2]","f":"The stillness at the storm's heart swallows the field. Blades and spells halt, and in return the callers' breath is worn away.","b":"{All foes} no attack/counter|{All allies} ♥−2","h":"1razkh5"},
"RB1-1": {"n":"Lay Powder Kegs","t":"Place a lit powder keg (0/0/2) in this spell's slot and each empty allied slot. Kegs don't attack or counter on the turn they are placed, and can be destroyed by spells or attacks (a destroyed keg fizzles). Before the first attack next turn, kegs explode: the enemy unit in the same slot number gets [Burn 3].","f":"Each time Fortan fell, goblins rolled kegs into empty trenches. The fewer the defenders, the louder the blast.","b":"{Empty ally slots} keg|Next turn, same-slot foe Burn 3","h":"g2bwot"},
"RB2-1": {"n":"Workshop Self-Destruct","t":"Destroy all allied units, then all enemy units: HP −7. [Reload 2]","f":"In the end the workshop master gave the order. The golems' hearts burst at once and a whole mine shaft collapsed.","b":"{All allies} Destroy|{All foes} ♥−7","h":"wc04q2"},
"RB3-1": {"n":"Keraun Overdischarge","t":"All enemy units: HP −2 −2C×3. All allied units: HP −3. [Reload 2]","f":"All the lightning in Keraun's nerves, drawn out at once. The sleeping giant shuddered and the plateau blazed white.","b":"{All foes} ♥−2 −2C×3|{All allies} ♥−3","h":"c9p9i"},
"RG1-1": {"n":"Chieftain Hunt","t":"Destroy the 3 enemy units with the highest ATK. Also destroy all allied units.","f":"The whole pack throws itself at the chieftain's throat. When the hunt ends, only wind remains on the steppe.","b":"{Top-ATK foes 3} destroy|{All allies} destroy","h":"1w61ymu"},
"RG2-1": {"n":"Forest Hush","t":"All units on both sides: ATK becomes 0. All enemy units: HP −3. [Reload 3]","f":"The whole forest holds its breath. In a stillness where bird, wind and blade all stop, only the thorns slowly grow.","b":"{Both sides} ⚔=0|{All foes} ♥−3","h":"1rrwhbw"},
"RG3-1": {"n":"Great Tsunami","t":"All units on both sides: HP −4. Then your front-most unit gains [Heal 1] this turn.","f":"Talakus's pulse beats once, hard. The sea swallows everything, then gives breath back only to the merfolk.","b":"{All units} ♥−4|{Ally front 1} [Heal 1]","h":"900ycz"},
"RS-A1-1": {"n":"Blood Lance","t":"[Offering 2] 1 enemy unit with the highest ATK: HP −6.","f":"A spear forged from one's own hardened blood. Noctar's pactbound pierce the deadliest foe first.","b":"{Offering} Life 2|{Foe top ATK 1} ♥−6","h":"dupzsj"},
"RS-A1-2": {"n":"Vampiric Veil","t":"The enemy's front 2 units: ATK −4 (not below 0). Allied front unit: ATK + the total reduced, and HP +2.","f":"The shadows of Mork Gorge drain the strength of those who approach and feed it to the gatekeeper. The other side always pays.","b":"{Foe front 2} ⚔−4|{Ally front 1} ⚔ + amount reduced, ♥+2","h":"1tzgdxs"},
"RS-A1-3": {"n":"Mind Control","t":"Among enemy units under [Curse] or of Level 3 or lower, bring 1 with the highest ATK to the back of your Field this turn to fight on your side. If it survives, it returns to the back of the enemy Field when battle ends.","f":"The new moon's whisper creeps first into frightened hearts. The soldier who raised his blade at yesterday's comrade remembers his own name only after sundown.","b":"{Foe [Curse] or L3 or lower · top ⚔ 1} Yours this turn|If alive, back to the foe's rear","h":"15q4ell"},
"RS-A2-1": {"n":"Judgment of Light","t":"Allied front 2 units' DEF becomes 0 this turn. Reduce the enemy front unit's HP by the total DEF lost; after a defeat, the rest goes to the next unit.","f":"On judgment day, Dawnhold's knights lay down their shields. The light gathered in them becomes a single spear piercing the enemy ranks.","b":"{Ally front 2} ⛨ → 0|Total ⛨ lost → {Foes from front} ♥− (rest to next)","h":"dvvj6u"},
"RS-A2-2": {"n":"Light of Retribution","t":"All allied units gain [Aegis 1]. At the end of battle, reduce the HP of the enemy unit with the highest HP by the damage your allies blocked with [Barrier] · [Aegis] this turn.","f":"Blades stopped by Celestial wings do not vanish. They gather as light, and the moment the fight ends, return to those who swung them.","b":"{All allies} [Aegis 1]|Blocked damage → {Top-♥ foe 1} ♥−","h":"1kvdg3k"},
"RS-A2-3": {"n":"Ward of Light","t":"Allied front unit gains [Barrier]. Enemy front unit: ATK −3, HP −1.","f":"A circle of light is drawn before those sworn to Solante. Any blade crossing it is blinded and loses its strength.","b":"{Ally front 1} [Barrier]|{Foe front 1} ⚔−3 ♥−1","h":"1vqmms4"},
"RS-A3-1": {"n":"Cutting Wind","t":"A random enemy unit: HP −2, 2 times.","f":"The first wind art a Storm Tower novice learns. Wind honed like a blade splits armor gaps before any arrow.","b":"{Foe random} ♥−2 ×2","h":"1hfb5g2"},
"RS-A3-2": {"n":"Headwind Barrier","t":"Enemy front 3 units: ATK −3, HP −1.","f":"Those who would climb the Needle Spire first meet a wind blowing backward. A thrust blade comes back at its own face.","b":"{Foe front 3} ⚔−3 ♥−1","h":"1elfb91"},
"RS-A3-3": {"n":"Whirlwind Blades","t":"A random enemy unit: HP −2, 3 times. All enemy units: ATK −1.","f":"A whirlwind descended from atop Belumir's Needle. Its wind blades are countless, and those caught cannot even stand.","b":"{Foe random} ♥−2 ×3|{All foes} ⚔−1","h":"1h6sk4s"},
"RS-B1-1": {"n":"Sea of Fire","t":"All enemy units: HP −3. Enemy front 2 units: HP −3 more. [Reload 1]","f":"Fortan's artillery doesn't calculate. It pours out all the powder it has and refills the next day.","b":"{All foes} ♥−3|{Foe front 2} ♥−3 more","h":"1eibafa"},
"RS-B1-2": {"n":"Buried Mines","t":"Enemy front 2 units: HP −2.","f":"On the road up Sawtooth Pass lie stones only goblins know. Stones you must not step on.","b":"{Foe front 2} ♥−2","h":"fs0sn2"},
"RS-B1-3": {"n":"Ember Barrage","t":"All enemy units: HP −1 −1C. Among them, 1 unit with the highest ATK: HP −2 more.","f":"Shells each holding a fistful of Dormak's Heartfire. The scattered embers gather on whoever raises the biggest blade.","b":"{All foes} ♥−1 −1C|{Highest-ATK foe 1} ♥−2 more","h":"1smgv2q"},
"RS-B2-1": {"n":"Shatter Hammer","t":"Opponent's 2 front units: DEF −2, HP −2.","f":"Durkheim's artisans know how to make armor, so they know how to break it. Strike a single seam.","b":"{Foe front 2} ⛨−2 ♥−2","h":"czr86f"},
"RS-B2-2": {"n":"Golem Phalanx","t":"All allies: DEF +1, HP +2, [Aegis 2], [Curseproof].","f":"Golems shoulder to shoulder become a spur of the Ironframe Range. No spell can squeeze through.","b":"{All allies} ⛨+1 ♥+2|{All allies} [Aegis 2] [Curseproof]","h":"1c79018"},
"RS-B2-3": {"n":"Rivet Storm","t":"All allies: DEF +1, HP +1. All enemy units: DEF −1, HP −2.","f":"The workshop's rivet machines all flipped at once. Rivets seeking a home lodged in allied armor and tore through the foe's.","b":"{All allies} ⛨+1 ♥+1|{All foes} ⛨−1 ♥−2","h":"foifh1"},
"RS-B2-4": {"n":"Iron Wall Advance","t":"All allied units: DEF +1. Then, starting from your front unit, allies gain ATK equal to the total DEF of all allied units — 1 less for each step back.","f":"Durkheim's shield line never retreats. The moment it surges forward, the weight of all behind makes the front shield a hammer.","b":"{All allies} ⛨+1|{All allies} ⚔ + total ⛨ (−1 per step back)","h":"1m3qlx3"},
"RS-B3-1": {"n":"Capacitor Unleashed","t":"From the front of the enemy Line, in order: HP −2 → −2 → −2.","f":"Three of Voltarium's capacitor jars, linked in a row. The lightning crosses to the next undiminished.","b":"{Foe from front} In order ♥−2→−2→−2","h":"18pxdu4"},
"RS-B3-2": {"n":"Shock Trap","t":"All enemy units: ATK −2, HP −1 −1C×2.","f":"Copper wire lines a gnome workshop's threshold. The blade of whoever crosses drops from their hand.","b":"{All foes} ⚔−2|{All foes} ♥−1 −1C×2","h":"uvi99t"},
"RS-B3-3": {"n":"Fully Charged","t":"This turn, allied units' Coins: every + Coin lands heads, every − Coin lands tails. Enemy front 2 units: HP −2 −1C.","f":"The gauge is full. On such days, gnome machines have never once missed.","b":"{Allies} All Coins favorable|{Foe front 2} ♥−2 −1C","h":"zvxs3j"},
"RS-G1-1": {"n":"Wolf Ambush","t":"Front enemy unit: HP −2. 2 allied units: ATK +1, [Sunder].","f":"A Howling Steppe wolf bites first, and the orc on its back tears open the gap in the armor.","b":"{Foe front 1} ♥−2|{Ally 2} ⚔+1 [Sunder]","h":"18d27va"},
"RS-G1-2": {"n":"Blood Oath","t":"Bind each allied unit with blood (🩸). When a bound unit is defeated, all the blood it holds passes to the ally right behind it. At the end of battle, a unit that survives holding others' blood gains ATK at next turn's prep equal to the ATK those owners had when defeated (that turn only).","f":"Garun's orcs cut their palms and mix blood. The rage of the first to fall wakes again in the fist of the brother behind.","b":"{All allies} 🩸 bind|Defeated: 🩸→behind|Next turn ⚔+(fallen ⚔)","h":"rhsn2y"},
"RS-G1-3": {"n":"Earthsplitter","t":"Front enemy unit: DEF −1. All enemy units: 3 physical damage. All allies: ATK +1.","f":"The orc song of splitting the earth with one fist is no exaggeration. Gorvath merely allowed that fist.","b":"{Foe front 1} ⛨−1|{All foes} phys dmg 3|{All allies} ⚔+1","h":"1kd9qka"},
"RS-G2-1": {"n":"Root Ambush","t":"3 enemy units: HP −2. 2 allied units: HP +2.","f":"Roots crawling underground rise behind the foe. What they draw up becomes allied sap.","b":"{Foe 3} ♥−2|{Ally 2} ♥+2","h":"x82oq3"},
"RS-G2-2": {"n":"Bramble Thicket","t":"All allies: HP +3, [Thorns 2].","f":"The paths outside Sylvaniel close with brambles overnight. Whoever cuts their way in is pricked as much as they cut.","b":"{All allies} ♥+3 [Thorns 2]","h":"1mbkyes"},
"RS-G2-3": {"n":"Stubborn Moss","t":"All allies: HP +2, [Indomitable].","f":"The moss on a troll's body won't let its host fall. Its drifting spores choke the foe.","b":"{All allies} ♥+2 [Indomitable]","h":"1yx1wyd"},
"RS-G3-1": {"n":"Harpoon Current","t":"The enemy's front-most unit loses [Barrier]·[Thorns]·[Curseproof]·[Guard], and HP −3. Your front-most unit gains [Heal 1] this turn.","f":"A harpoon riding the current washes away shield and blessing alike as it strikes. Selenea's hunters never throw twice.","b":"{Foe front 1} remove · ♥−3|{Ally front 1} [Heal 1]","h":"197qc9h"},
"RS-G3-2": {"n":"Seafoam Veil","t":"Your front-most unit gains [Barrier], and [Purify] this turn. All allies: HP +1.","f":"The seafoam song of the Wellspring Maidens. The first blade slips on the foam; wounds close under droplets.","b":"{Ally front 1} [Barrier] · [Purify]|{All allies} ♥+1","h":"k63n8"},
"RS-G3-3": {"n":"Song of the Flood","t":"All enemy units' Coins turn tails (Coins already decided stay). All enemy units: HP −2. All allies: HP +1. Your front-most unit gains [Heal 1] this turn.","f":"A song timed to the hour Marencia's sea rises. The incoming water sweeps away the foe's luck and wets allied feet.","b":"{All foes} Coins tails · ♥−2|{All allies} ♥+1|{Ally front 1} [Heal 1]","h":"12z4rrw"},
"S2-1": {"n":"Sigil of Light","f":"Solante's holy sigil. Each turn, it dulls the first blade that flies in.","h":"1s3ulxc"},
"S3-1": {"n":"Seal of the Pact","f":"The seal of a pact made with Morkas. Its price paid in advance, the blades of those larger than you slip past like shadows.","h":"x11xwr"},
"S4-1": {"n":"Solante's Relic","f":"The sun god's relic. On the day the god looks away, it stops nothing.","h":"1ydhivb"},
"SA1-01": {"n":"Call of the Abyss","t":"[Offering 2] Revive in this slot one unit from your Pyre whose Level is at most the Offerings paid this turn (the highest Level). The revived unit stays on the Field.","f":"The scale of Morkas weighs the dead too. When the living pile on enough blood, someone rises from the opposite pan.","b":"{Offering} Life 2|{Self} Revive 1 Pyre unit (Level ≤ Offerings)","h":"xyfz8a"},
"SA1-02": {"n":"Shadow Grasp","t":"Seize one enemy unit whose Level is at most (Offerings paid this turn + 1) (the highest Level) and place it at the back of your Field. It fights as your unit this turn and disperses when battle ends (to its owner's Pyre).","f":"The shadow underfoot becomes a hand that grips the foe. The more blood offered, the larger the prey it drags in.","b":"{Foe 1} Seize (Level ≤ Offerings +1) · this turn","h":"6tn8wm"},
"SA1-04": {"n":"Mirror Phantom","t":"[Offering 2] Summon to this slot a phantom of 1 enemy unit with the highest ATK. The phantom is the same card as that unit (no items), fights on your side this turn, and vanishes when battle ends.","f":"Those reflected in Morkas's mirror fight their own shadow. It borrows the original's strength in full, but never its armor.","b":"{Offering} Life 2|Phantom of {Foe top ATK 1} on your side · this turn","h":"p2gzr"},
"SA1-06": {"n":"Blood Tithe","t":"Each allied unit: HP −1. The enemy's front unit loses HP equal to 3 times the total HP lost. Any excess after defeating it carries over to the next unit.","f":"Noctar's pactbound slit their palms to feed the blade. The more blood spilled, the farther the blade reaches.","b":"{All allies} ♥−1|{Foe front 1} ♥− total ×3, excess to next","h":"gm8qhl"},
"SA2-01": {"n":"Charge Horn","t":"Allied front 2 units: ATK +1 +1C.","f":"A horn sounds on Dawnhold's walls. The front-rank knights charge with the sun at their backs.","b":"{Ally front 2} ⚔+1 +1C","h":"j6lisq"},
"SA2-02": {"n":"Prayer of Endurance","t":"Allied front 2 units gain [Aegis 1].","f":"It is darkest before dawn. In that dark, Celestials count each blade they take like a prayer — and dawn breaks as far as they count.","b":"{Ally front 2} [Aegis 1]","h":"ca3rze"},
"SA2-03": {"n":"Prayer of Silence","t":"Disable the abilities of the enemy front 2 units this turn. If you have a [Purify] unit, all enemy units instead.","f":"When Celestial priests pray as one, the battlefield's din subsides. In that silence, no power can call its own name.","b":"{Foe front 2} Abilities off|With [Purify]: {All foes}","h":"lznqdl"},
"SA2-04": {"n":"Righteous Strike","t":"Enemy front unit: HP −2. Allied front unit gains [Barrier].","f":"As the sword falls, light returns to wrap its wielder. Justice guards even the one who strikes.","b":"{Foe front 1} ♥−2|{Ally front 1} [Barrier]","h":"7kkx4z"},
"SA2-07": {"n":"Scales of Judgment","t":"If 2 or more enemy units share the same ability, each of them loses ATK equal to its own Level this turn.","f":"Solante's scales weigh together those who wield the same power in a pack. The heavier one's rank, the lighter one's blade.","b":"{Foes, same ability 2+} ⚔ −Level","h":"dy74t"},
"SA3-01": {"n":"Gust","t":"Enemy front unit: DEF −1 −1C. 2 allied units: ATK +1.","f":"A gust from the front pries open the foe's armor. The same wind pushes the backs of comrades behind.","b":"{Foe front 1} ⛨−1 −1C|{Ally 2} ⚔+1","h":"1onax43"},
"SA3-02": {"n":"Confounding Wind","t":"Swap the enemy front unit's DEF and remaining HP (a unit with 0 DEF drops to 0 HP and is defeated).","f":"Elven wind does not strip armor. It only muddles body and armor until neither knows which is which. The arrow handles the rest.","b":"{Foe front 1} ⛨ ↔ ♥","h":"1nm3yzd"},
"SA3-04": {"n":"Draw the String","t":"Allied front 2 units: ATK +2 +1C, [Ranged].","f":"The Guild's archers draw their strings to the ear as one. At this range, no blade can reach.","b":"{Ally front 2} ⚔+2 +1C|[Ranged]","h":"1lk717t"},
"SA3-05": {"n":"Rebounding Wind","t":"Allied front 2 units: DEF +2, HP +2, [Bypass] (this turn — also ignores enemy DEF when countering).","f":"Needle Spire archers do not yield under blows. While a whirlwind turns aside the blade, the string already aims at a gap in its wielder's armor.","b":"{Ally front 2} ⛨+2 ♥+2 [Bypass]","h":"15l24s1"},
"SA3-06": {"n":"Guild Armory","t":"All allied units with no item equipped take up a [Bow] (for the whole match). Units given a bow: ATK +2 and [Ranged] this turn.","f":"The armory of the Storm Tower Guild opens. Hands that held swords, and beasts with only claws, each grasp a wind-wrapped bow.","b":"{Allies w/o item} 🏹[Bow] (whole match)|⚔+2 [Ranged]","h":"lr6me5"},
"SA3-08": {"n":"Great Tempest","t":"All enemy units: ATK −1 −1C. The enemy front unit neither attacks nor counters this turn.","f":"The signal for the Storm Tower Guild to loose as one. Before the arrows, a wind too strong to stand in sweeps the field.","b":"{All foes} ⚔−1 −1C|{Foe front 1} no attack/counter","h":"qvpzs2"},
"SB1-01": {"n":"Smoke Bomb","t":"3 enemy units: ATK −2. Those with Burn get ATK −2 more.","f":"Acrid powder smoke covers the field. Those caught by fire cannot open their eyes in it.","b":"{Foe 3} ⚔−2|If Burned, ⚔−2 more","h":"zz1t3w"},
"SB1-03": {"n":"Curtain of Fire","t":"Allied front 2 units: HP +1, [Flame Armor 2].","f":"Oil is poured before the trench and set alight. Whoever climbs over with a blade goes back wearing fire.","b":"{Ally front 2} ♥+1|[Flame Armor 2]","h":"2tjm2z"},
"SB1-05": {"n":"Detonate","t":"Enemy front unit: Burn 2. Then detonate all Burn on enemy units now — units that had Burn take 2 more damage.","f":"Fortan sappers don't wait for embers to flare on their own. One signal, and every fire set bursts at once.","b":"{Foe front 1} Burn 2|{Foe Burn} detonate now +2","h":"ogb6g9"},
"SB1-06": {"n":"Defense Battery","t":"2 enemy units: HP −3.","f":"Cannons hidden behind the walls aim at the rear ranks of the advancing foe. The front ranks knew only when they looked back.","b":"{Foe 2} ♥−3","h":"3oidc"},
"SB1-08": {"n":"Powder Store Blast","t":"Detonate and destroy all N of your powder kegs. For each keg detonated, enemy units: HP −N², [Burn 2]. All allied units: HP −N.","f":"When one ember falls into Dormak's powder store, every keg in Fortan answers in the same breath.","b":"{Your kegs N} destroy|{Foe N} ♥−N² Burn 2|{All allies} ♥−N","h":"r137yy"},
"SB1-09": {"n":"Grand Bombardment","t":"All enemy units: HP −3. [Reload 2]","f":"The whole battery fired as one breath. The field has had a different shape ever since.","b":"{All foes} ♥−3","h":"law91g"},
"SB2-01": {"n":"Ironclad Charge","t":"2 allied units: ATK +2, DEF +1.","f":"Iron-clad dwarves charge shoulder to shoulder. Slow, but once started, no one can stop them.","b":"{Ally 2} ⚔+2 ⛨+1","h":"1p54com"},
"SB2-02": {"n":"Rivet Launcher","t":"Opponent's front unit: DEF −2, HP −1.","f":"It fires rivets heated by compressed steam. Armor or shield, it pierces either.","b":"{Foe front 1} ⛨−2 ♥−1","h":"8d5f8y"},
"SB2-03": {"n":"Weld Repair","t":"Your front unit: HP +2 +1C.","f":"Even mid-battle they weld cracked iron in a shower of sparks. To a Durkheim artisan, the battlefield is a workshop too.","b":"{Ally front 1} ♥+2 +1C","h":"142q9gb"},
"SB2-06": {"n":"Crushing Press","t":"Opponent's front unit: HP −1. 3 allied units: ATK +1.","f":"They dragged the workshop's great press onto the battlefield. Strength that flattened iron proved good for flattening foes.","b":"{Foe front 1} ♥−1|{Ally 3} ⚔+1","h":"1ojbgaa"},
"SB2-09": {"n":"Grand Workshop","t":"All allies: DEF +1, HP +1 +1C. All allies gain [Curseproof].","f":"Every furnace in Durkheim is lit. The whole underground city becomes one workshop backing the fight.","b":"{All allies} ⛨+1 ♥+1 +1C|{All allies} [Curseproof]","h":"1n4eff1"},
"SB3-01": {"n":"Static","t":"3 enemy units: HP −1 −1C.","f":"A tiny spark from rubbed fur. Gnomes teach that every great experiment began with this.","b":"{Foe 3} ♥−1 −1C","h":"1gjl2h5"},
"SB3-02": {"n":"Lightning Rod","t":"Enemy front 2 units: ATK −1 −1C×2.","f":"Steals the sky's lightning and turns it to the ground. This is why Astrak counts Voltarium a foe.","b":"{Foe front 2} ⚔−1 −1C×2","h":"14gv97z"},
"SB3-03": {"n":"Charge Coil","t":"Allied front 2 units: ATK +1 +1C×2.","f":"Copper wound thousands of times holds lightning fast. The more you wind, the louder the hum at your fingertips.","b":"{Ally front 2} ⚔+1 +1C×2","h":"8rboxv"},
"SB3-04": {"n":"Shock Veil","t":"3 enemy units: HP −1 −1C×2.","f":"A veil of lightning hung before Voltarium. Those crossing went numb from the fingertips and halted.","b":"{Foe 3} ♥−1 −1C×2","h":"7xf69h"},
"SB3-05": {"n":"Capacitor Wall","t":"Allied front 2 units: DEF +1. Enemy front unit: HP −2 −1C.","f":"Capacitors lined up into a wall of lightning. Any blade that touched it bit its owner's hand first.","b":"{Ally front 2} ⛨+1|{Foe front 1} ♥−2 −1C","h":"1k6glkn"},
"SB3-06": {"n":"Call Thunderclouds","t":"All enemy units: HP −1 −1C.","f":"Plateau clouds hauled in by machine. When the storm reached overhead, the gnomes opened umbrellas.","b":"{All foes} ♥−1 −1C","h":"1yxmj3w"},
"SB3-09": {"n":"Thunderstorm","t":"All enemy units: HP −1 −1C×2.","f":"The plateau's whole storm moved over Voltarium. That day more lightning fell than rain.","b":"{All foes} ♥−1 −1C×2","h":"1pvuhdk"},
"SG1-01": {"n":"Drive the Prey","t":"Reorder enemy units from the front by lowest remaining HP.","f":"Orc hunters drive out the weakest beast first. Shoved to the front, it has nowhere to flee the fangs.","b":"{Foes} ♥ lowest first, from front","h":"x41fjm"},
"SG1-02": {"n":"Finishing Bite","t":"All enemy units: HP −1.","f":"Orcs never turn their backs on a staggering foe. Those still holding on in their fangs are finished one by one.","b":"{All foes} ♥−1","h":"196y8u"},
"SG1-03": {"n":"Cornered Fangs","t":"Total the ATK of all allied units. Starting from the front enemy unit, strip that amount from ATK → DEF → HP in order (ATK and DEF this turn). If it is defeated, the rest carries over to the next unit.","f":"The cornered pack sinks its fangs all at once. The one in front loses claws, armor, then breath.","b":"{Foes from front} ⚔ → ⛨ → ♥ strip|Amount = {Allies} ⚔ total · rest carries on","h":"t4cs3v"},
"SG1-04": {"n":"Prey Mark","t":"Front enemy unit: DEF −2, HP −1.","f":"A hunter draws a line of earth across the foe's brow. The pack that sees it chases that one alone.","b":"{Foe front 1} ⛨−2 ♥−1","h":"g8e8ih"},
"SG1-08": {"n":"Fang Counter","t":"All allied units: HP +2, [Lethal].","f":"A cornered orc bites instead of retreating. Whoever attacked goes home, if at all, with one breath left.","b":"{All allies} ♥+2 [Lethal]","h":"11z4wsz"},
"SG1-09": {"n":"Body Slam","t":"All enemy units: HP −(allied units × 2). Then each allied unit: HP −(allied units).","f":"The pack hurls itself as one mass. The ones who hit break too, but the ones hit break worse.","b":"{All foes} ♥ −(allies×2)|{All allies} ♥ −(allies)","h":"oa4zza"},
"SG2-01": {"n":"Vine Constrict","t":"Deal damage (its DEF ×2) to 1 enemy unit with the highest DEF.","f":"Vines seek out armor joints. The thicker the armor, the deeper they dig and the harder they squeeze.","b":"{Top DEF foe 1} damage ⛨×2","h":"1qutwq4"},
"SG2-02": {"n":"Sprout Armor","t":"Allied front unit: DEF +1, [Regenerate 2].","f":"Shoots sprout in every crack of bark to cover wounds. Cut them, and they sprout again the next moment.","b":"{Ally front 1} ⛨+1 [Regenerate 2]","h":"1l8cbeo"},
"SG2-03": {"n":"Thorn Hedge","t":"2 allied units gain [Thorns 2].","f":"Overnight, brambles grow round the camp. Whoever climbs over will remember the thorns.","b":"{Ally 2} [Thorns 2]","h":"1mf2m6l"},
"SG2-04": {"n":"Treant March","t":"3 allied units: ATK +1, HP +3.","f":"The treants pull up their roots and walk. Slow strides, but nothing can halt them.","b":"{Ally 3} ⚔+1 ♥+3","h":"oz6jhn"},
"SG2-05": {"n":"Pooled Sap","t":"The allied unit with the highest HP (1 unit) takes all other allied units' HP, leaving each at 1 (+1 per giver). That 1 unit gains [Guard] this turn.","f":"The trolls press palms to an old tree's base. All their sap runs down the roots into that one tree, which swells fit to burst.","b":"{Allies} ♥ → 1|all to {Top ♥ 1} (+1 each) · Guard","h":"v5rmer"},
"SG2-07": {"n":"Thistle Fortress","t":"2 front-most allied units: DEF +1, [Thorns 2].","f":"Thistles shoot up into a rampart. Within it, the trolls at last have a wall to lean on.","b":"{Ally front 2} ⛨+1 [Thorns 2]","h":"16b6flv"},
"SG2-08": {"n":"Elder Tree Slam","t":"The allied unit with the highest HP has its HP halved (round down). Deal damage equal to the HP lost to enemy units with DEF 1 or more.","f":"The old tree heaves up, roots and all, and slams down with the weight of its sap. The ground caves in; the tree loses half its bark.","b":"{Top ♥ 1} ♥ halved|HP lost as damage to {All foes with DEF}","h":"17di8og"},
"SG2-09": {"n":"Verdan's Elder Tree","t":"All allies: DEF +1, [Thorns 2].","f":"A branch fallen from the dragon's antler grows into an old tree overnight. Beneath its thorny shade stand the Covenant's warriors.","b":"{All allies} ⛨+1 [Thorns 2]","h":"n1hfnc"},
"SG3-01": {"n":"Illusory Control","t":"Steal the front-most 1 enemy card whose name has the same letter count (excluding spaces) as your card right behind this spell, and place it at the back of your field. A unit is yours until the match ends; a spell resolves as your spell.","f":"Selenea's maidens sing names. Those whose names are the same length hear the song as their own and walk, dreamlike, into the underwater ranks.","b":"{Foe card 1, same length as next} steal","h":"8k684g"},
"SG3-02": {"n":"Shimmer Mirage","t":"Swap ATK and HP of 2 random enemy units.","f":"When the water shimmers, what the eye sees turns over. Giants sway like reeds; cowards slash at their own shadows. Only the waves know who.","b":"{Foe random 2} ⚔ ↔ ♥","h":"1dsu3pi"},
"SG3-03": {"n":"Veil of Water","t":"Your front 2 units take −1 damage this turn (clash, spell and thorns alike, as with the merfolk aura Sea's Shelter). Your front-most unit gains [Purify] this turn.","f":"A maiden lifts the water into a thin veil. Blades lose their strength passing through.","b":"{Ally front 2} damage taken −1|{Ally front 1} [Purify]","h":"qml8w0"},
"SG3-09": {"n":"Great Current","t":"All enemy units' Coins turn tails (Coin chance −50%; Coins already decided stay). Your front-most unit gains [Heal 1] this turn.","f":"The great current of the southern sea changes course. The luck the foe relied on drifts away with it.","b":"{All foes} Coins tails|{Ally front 1} [Heal 1]","h":"1n7dcvs"},
"SP-A1": {"n":"Azra the Shadowless","f":"The only one who sat across from Morkas, the Silent Lord, paid the price, and owed nothing. No one knows what she set on the scale. Since that day she casts no shadow even at sunrise, and every shadow in Noctar leans toward her.","h":"1xgn3b9"},
"SP-A2": {"n":"Solante's First Knight","f":"The first to swear an oath to Solante, Mother of Dawn. Hearing it, she lifted him up herself, and every oath of the Order of Radiance still echoes his words. Where he raises his sword, night cannot come.","h":"1okmck0"},
"SP-A3": {"n":"Isak, Star Unraveler","f":"The first to read the star letters. The night he finished, he unraveled a constellation and rewove it, and the sky obeyed. The Storm Tower Guild has yet to finish his first page.","h":"xbf6zi"},
"SP-B1": {"n":"Fire Swallower","f":"The one who swallowed the sleeping giant Dormak's Heartfire whole. Each breath is a battery's volley; the Firecrown Range burns only as it breathes. Fortan gunners never say its name — lest it answer.","h":"kn41n2"},
"SP-B2": {"n":"Ironheart Swallower","f":"One who swallowed an iron heart forged from the melted sinews of the giant Sorgrim. The day it first beat, every golem in Durkheim woke with it. Only the first golem he made still remembers his name was Bron.","h":"qvtsgi"},
"SP-B3": {"n":"The Seventh","f":"Voltarium wired six machines to the giant Keraun's nerves; all six burned out. The seventh opened its eyes. Is it Voltarium's design that thinks inside, or the sleeping giant's dream — even its makers now look up and await its answer.","h":"jladek"},
"SP-G1": {"n":"Karno Ashmane","f":"Recognized by Gorvath, Dragon of Earth, after a hundred duels. Some say the hundred-and-first foe was that very dragon. He still seeks the strong to duel, and where he passes, smoke like an ashen mane lingers over the steppe.","h":"w2ivlp"},
"SP-G2": {"n":"Silvermoon Lisiel","f":"A forest that walks only on waxing-moon nights. It took the flames of the burning Great Forest of Eilen with its whole body, and raised a thousand-year forest on the ashes overnight. Scholars split: spirit or ascendant?","h":"14but7z"},
"SP-G3": {"n":"She Who Stills the Sea","f":"The oldest song the water dragon Marencia remembers, given form. It keeps the giant Talakus asleep beneath the sea. As no blade cuts water, none cuts her. Lately the song grows longer.","h":"1cyfalk"},
"SR-A1": {"n":"Hargan's Greatsword","f":"The sword of Hargan the Judge. They say it was drawn only once, to punish a god. Before the verdict, armor means nothing.","h":"xp1q65"},
"SR-A2": {"n":"Seren's Bow","f":"The bow the gatekeeper Seren aimed beyond the world's edge. What tries to cross falls before it arrives.","h":"m8vcbu"},
"SR-A3": {"n":"Ivel's Quill","f":"The quill of Ivel the Chronicler. What it writes becomes what happened.","h":"c1i4qh"},
"SR-B1": {"n":"Dormak's Rib Brazier","f":"A brazier carved from a rib of the giant Dormak, lying beneath the Firecrown Range. An undying Heartfire burns inside and flares higher at anything already alight.","h":"1avidfj"},
"SR-B2": {"n":"Sorgrim's First Armor","f":"Armor torn whole from a rib joint of the sleeping giant Sorgrim. A blade stopped by it returns to its wielder with all its weight.","h":"1gh9fpp"},
"SR-B3": {"n":"Keraun's Thunderheart","f":"A shard of the giant Keraun's heart that lightning could not stop. With each spell it beats harder, loading thunder into the bearer's arm.","h":"dor3rf"},
"SR-G1": {"n":"Gorvath's Broken Fang","f":"A fang Gorvath, Dragon of Earth, broke on its first hunt. Its bearer grows like a dragon with every fallen foe devoured.","h":"ng31z6"},
"SR-G2": {"n":"Verdan's First Antler","f":"The first antler Verdan, the forest dragon, ever shed. Its roots drain attackers' breath to mend its owner's wounds.","h":"1t8161"},
"SR-G3": {"n":"Marencia's Tear Chalice","f":"A chalice holding the tears Marencia shed on the day of the pact. When battle begins, the flood reaches the deepest-cut first.","h":"2escw"},
"TK-A1-1": {"n":"Sealing-Wax Familiar","f":"A familiar given life, risen from sealing wax.","k":"Wax Spirit","h":"hlt51w"},
"TK-A2-1": {"n":"Knight of Light","f":"A knight shaped from a single oath of light. The oath does not bend, so neither does the sword.","k":"Oath Soul","h":"19rt2jo"},
"TK-B2-1": {"n":"Sentry Golem","f":"A small sentry golem the workshop activates in emergencies.","k":"Golem","h":"r9zczc"},
"TK-G1-1": {"n":"Shadow Hyena","f":"A hyena that leaps from shadow, bites once, and vanishes, leaving only laughter.","k":"Hyena","h":"5hiknq"},
"TK-G1-2": {"n":"Alpha Hyena","f":"Leader of the pack that answered the call. Its laugh is the lowest.","k":"Hyena","h":"1ssr25s"},
"TK-G2-1": {"n":"Vine Barrier","f":"A vine wall that grows and withers within one turn.","k":"Treant","h":"68dfdz"},
"TK-G3-1": {"n":"Water Spirit","f":"A small spirit risen from the spring.","k":"Undine","h":"1alq71y"},
"TK-U-BOMB": {"n":"Lit Powder Keg","f":"The fuse burns down. Once the first spells of the next battle pass, it blows.","k":"Bomb","h":"1salvm9"},
"TK-U-ROOT": {"n":"Root","f":"A root that sprang overnight from a felled tree's stump. It embraces the fallen and won't let go.","k":"Treant","h":"9k0vpf"},
"TK-U-SAPLING": {"n":"Sapling","f":"A sapling planted where a battle ended.","k":"Treant","h":"ja6kds"},
"TK-U-SCRAP": {"n":"Scrap Golem","f":"A golem built from fallen comrades' parts.","k":"Golem","h":"104wnt4"},
"TK-U-TREE": {"n":"Young Elder Tree","f":"A sapling that endured a turn, grown into a tree.","k":"Treant","h":"4pj5k0"},
"TK-U-WOLF": {"n":"Ash Dust Beast","f":"A beast risen from the dust at the high chief's howl. After the next fight, it scatters back to dust.","k":"Dust Beast","h":"awcmx"},
"TS-A3-1": {"n":"Meteor Shard","t":"Deal 1 damage to 1 random enemy unit.","b":"{Foe random} 1 damage","h":"82a3qh"},
"TS-A3-2": {"n":"Dust Devil","t":"Deal 2 damage to 1 random enemy unit.","b":"{Foe random} 2 damage","h":"a2bjhf"},
"TS-A3-3": {"n":"Ember","t":"Deal 1 damage to the enemy front unit.","b":"{Foe front 1} 1 damage","h":"8g635z"},
"TS-A3-4": {"n":"Twin Echo","t":"Deal 1 damage to the enemy front 2 units.","b":"{Foe front 2} 1 damage","h":"85g62x"},
"UN-A1": {"n":"Blood Oathsworn","f":"A vampire lord of Noctar's Abyss Pact who wrote his oath in his own blood. Those his blade cuts share the contract's price.","k":"Vampire Lord","h":"wutze8"},
"UN-A1-7": {"n":"Soul Reaper of Morkas","f":"An abyssal lord who gave his soul to Morkas and lost his body. Each soul his empty obsidian armor reaps leaves a contract in his hand, but his own has not yet been returned.","k":"Abyss Lord","h":"mvj33j"},
"UN-A2": {"n":"Wingshield of Elad","f":"A radiant knight of Elad, the Dawnhold. It spreads its wings before comrades and takes the blows.","k":"Winged Colossus","h":"i7ib0t"},
"UN-A2-7": {"n":"Solante's Dawn Priest","f":"A sun apostle holding Solante's dawnlight in a golden ring. Where he walks the sun rises, and fallen knights stand again.","k":"Sun Apostle","h":"qg8by5"},
"UN-A3": {"n":"Spire Starkeeper","f":"A starscale dragon coiled around Belumir's Needle Spire, reading stars and wind alike. Before a foe's spell rides the wind, its eyes are already turned that way.","k":"Starscale Dragon","h":"7wdf52"},
"UN-A3-7": {"n":"Belumir's Spellhunter","f":"A starglass colossus that shoots down only others' spells. It sees a spell's light first, and spells skewered on its arrows are drawn into its crescent bow.","k":"Starglass Colossus","h":"1tr35y6"},
"UN-B1": {"n":"Fortan Artillery Chief","f":"A horned fire fiend who leads Fortan's powder artillery. Even as it falls, it lights a fuse.","k":"Fire Fiend","h":"d5e58f"},
"UN-B1-7": {"n":"Talakus Ember Gunner","f":"A lava dragon that plants embers scooped from Talakus's pulse into its shells. Where they land still burns the next day.","k":"Lava Dragon","h":"1xs40rd"},
"UN-B2": {"n":"Bron's First Golem","f":"The first golem the Ironheart Swallower made, and the last who remembers when its master was called Bron. It gathers fallen comrades' parts to build new golems.","k":"Golem","h":"c6gzjv"},
"UN-B2-7": {"n":"Durkheim Chain Golem","f":"The two golems guarding Durkheim's gates, bound by one steel chain. When one is struck, both hold fast.","k":"Golem","h":"16cgxr3"},
"UN-B3": {"n":"Zrak's Jarkeeper","f":"Voltarium's copper-masked thunder god who once jarred Zrak, great spirit of lightning. Each brush of magic refills the empty jar with lightning.","k":"Thunder God","h":"qyolsh"},
"UN-B3-7": {"n":"Keraun Magnet Tower","f":"A walking tower wound with Keraun's lightning. It twists even the luck of those who approach.","k":"Thunder Tower","h":"1yu40j3"},
"UN-G1": {"n":"Rockfang High Chief","f":"Leader of Garun's Rockfang tribe. When he fells a foe, the horde comes howling.","k":"Fang Giant","h":"1ailes7"},
"UN-G1-7": {"n":"Plunder King of Garun","f":"A six-armed giant king who takes up a fallen foe's weapon on the spot. In Garun, that is called courtesy.","k":"Six-Armed Giant","h":"ekaadj"},
"UN-G2": {"n":"First Tree Thornkeeper","f":"An old treant growing brambles round Sylvaniel's First Tree. Cut it down, and the roots remain.","k":"Treant","h":"1keyu36"},
"UN-G2-7": {"n":"Verdan's Seedkeeper","f":"An old treant walking with seed pouches on every branch. Wherever a battle ends, a forest grows.","k":"Treant","h":"1ookx8c"},
"UN-G3": {"n":"Wellspring Singer","f":"A singer of Selenea's Wellspring Maidens. The dead who hear her return to the sea, then wash back in.","k":"Coral Goddess","h":"q6eslk"},
"UN-G3-7": {"n":"Marencia's Siren","f":"A siren risen with song from Marencia's deep waters. Foes who hear it to the end grip their swords backward.","k":"Siren","h":"8d7oi9"},
"UP-A1-09": {"n":"Mork Spider Queen","f":"She spun webs over a whole gorge wall, and spiderlings came. Now whatever falls into Mork Gorge pays her share first.","k":"Shadow Spider","h":"og5fno"},
"UP-A1-11": {"n":"Pact Rat Vanguard","f":"Of three warriors, the one who came back carries the other two's contracts too.","k":"Rat","h":"hynxsu"},
"UP-A1-15": {"n":"Bloodsip Demonblade","f":"The bloodsip blade drank three owners dry and became a demon blade. It no longer waits for a hand to wield it.","k":"Cursed Sword","h":"1leesj1"},
"UP-A1-18": {"n":"Shadow Slaughterer","f":"It does not wait in the shadows. It drags them along.","k":"Shadow Beast","h":"jwd1jy"},
"UP-A1-23": {"n":"Great Scythe Reaper","f":"He changed scythes when the reaped contracts piled knee-high. Now he calls names not one by one, but a row at a time.","k":"Reaper","h":"131wxen"},
"UP-A2-11": {"n":"Lancehorn Unicorn","f":"Its horn has grown as long as a lance. Darkness splits before the dawnlight at its tip even arrives.","k":"Unicorn","h":"z1vpbh"},
"UP-A2-15": {"n":"Solante's Vow Knight","f":"Only those who kept their oath three times wear the armor of vows.","k":"Holy Statue","h":"1pguka6"},
"UP-A2-17": {"n":"Golden Sphinx","f":"The questioning sphinx turned gold from long basking in Solante's light. Now, unasked, lies lose their shadows before it.","k":"Sphinx","h":"1cf5u3u"},
"UP-A2-22": {"n":"Solante's Great Bell","f":"The morning bell was moved to the cathedral's summit. Now its sound reaches the Twilight Wall.","k":"Bell Spirit","h":"x6h1bp"},
"UP-A2-24": {"n":"Great Mirror of Light","f":"The cloister mirror grew threefold. Into the silver of its back is mixed stone dust from the Twilight Wall.","k":"Mirror Spirit","h":"1a105v9"},
"UP-A3-10": {"n":"Rapidfire Harpy","f":"It never learned to save its feathers. Instead they grow back as fast as they fall.","k":"Harpy","h":"dxkn79"},
"UP-A3-11": {"n":"Gale Griffin","f":"The chick's habit of beating the news grew up with it. Now it arrives before the wind and becomes the news itself.","k":"Griffin","h":"19983x5"},
"UP-A3-18": {"n":"Gemini Archmaster","f":"The two stars learned to make their bowstrings sing as one. Now Gemini's arrows fly as one and strike as two.","k":"Constellation","h":"u660e3"},
"UP-A3-23": {"n":"Star Fox Ranger","f":"Having walked every plateau path, the star fox now smells which way the foe will come. The starlight on its tail has grown as long.","k":"Star Fox","h":"17d8k7l"},
"UP-A3-24": {"n":"Thunder Tengu Captain","f":"Loading lightning onto arrows it mastered long ago. Dropping it only where it wants, it stands alone in the Needle Spire.","k":"Tengu","h":"1y4zj2m"},
"UP-B1-12": {"n":"Demolition Chief","f":"The leader of the fire rats, who dug deepest under the powder store. Fortan sappers buried charges along its tunnels and finally named it their chief.","k":"Fire Rat","h":"16ib0od"},
"UP-B1-17": {"n":"Great Gun Tortoise","f":"After a hundred more years, the battery tortoise's shell crater split into three. One breath makes three sounds, but the ground caves in once.","k":"Lava Tortoise","h":"1yqm75z"},
"UP-B1-18": {"n":"Fire Ant Bulwark","f":"The fire ants guarding the powder store locked shells into a single wall. The more they are hit, the hotter and harder their shells.","k":"Fire Ant","h":"rfohvm"},
"UP-B1-24": {"n":"Master Mortarman","f":"Fortan's mortarmen correct their angles by watching its shells fly.","k":"Wolverine","h":"4xq7hs"},
"UP-B2-12": {"n":"Master Smith","f":"He melted three apprentice hammers to forge one master's hammer.","k":"Iron Monkey","h":"9zn1x8"},
"UP-B2-17": {"n":"Ironhorn Goat King","f":"The Ironhorn Goat shed its horns many times and became king of the herd. The herd lines up only behind him, and his back is the wall.","k":"Ironhorn Goat","h":"1qa9v1z"},
"UP-B2-18": {"n":"Steam Bull Chieftain","f":"The Steam-Snort Bull grew to three boilers in its belly and became head of the herd. One stamp echoes to the end of the mine.","k":"Bronze Bull","h":"n7u0co"},
"UP-B2-22": {"n":"Bulgasari King","f":"The Iron-Eating Bulgasari swallowed a whole workshop scrap heap and grew again. Now its herd trails behind, picking up the crumbs.","k":"Bulgasari","h":"vzyct2"},
"UP-B2-24": {"n":"Gargoyle Gatewarden","f":"The Ironframe Gargoyle took its seat above the gate of Durkheim's deepest mine. It does not say what lies beyond.","k":"Steel Gargoyle","h":"93qw6e"},
"UP-B3-12": {"n":"Discharge Sprite Queen","f":"A sprite that burst thrice without vanishing became queen. The fourth time it did not burst; now it chooses when to.","k":"Spark Fairy","h":"13pxikp"},
"UP-B3-18": {"n":"Tarsier Chief Engineer","f":"Merged in one night the designs three engineers had fought over.","k":"Tarsier","h":"q9f7e1"},
"UP-B3-22": {"n":"Shock Colossus","f":"Three sentinels' coils wound onto one body. Come close and the lightning strikes first.","k":"Thunder Engine","h":"73x9hw"},
"UP-B3-23": {"n":"Elder Professor in a Jar","f":"Wired by copper to two other professors' jars. The theories the three once argued now argue endlessly in one jar.","k":"Brain in a Jar","h":"1deyw8y"},
"UP-G1-11": {"n":"Obsidian Spearmaster","f":"Only after changing the obsidian tip three times did the spear feel like its own.","k":"Mongoose","h":"ugydye"},
"UP-G1-18": {"n":"Ogre High Shaman","f":"An ogre that finally heard all of Grom's first syllable. Now when it drums, the earth answers the rest.","k":"Ogre","h":"dzoeh"},
"UP-G1-24": {"n":"Hyena Grand Packleader","f":"It beat three packleaders and bound the steppe's hyenas into one. When it laughs, the steppe goes still.","k":"Hyena","h":"1ucq22h"},
"UP-G2-17": {"n":"Toad Archshaman","f":"He skipped three hibernations to master his craft. The moss obeys him.","k":"Moss Toad","h":"obr1rh"},
"UP-G2-22": {"n":"Mandrake Gatewarden","f":"It walked from the soil itself to stand at the Thornwood gate. Now one scream shuts the gate.","k":"Mandrake","h":"183ceud"},
"UP-G2-23": {"n":"Drien's High Apostle","f":"Apostles who bore Drien's word three ways became a single voice.","k":"Dryad","h":"1yar7ga"},
"UP-G3-11": {"n":"Tide Prophet Octopus","f":"Once it read the tides; now it decides when they turn. It spends seven of its eight arms on the task.","k":"Octopus","h":"txyjed"},
"UP-G3-12": {"n":"Coralback Elder Turtle","f":"Its coral grew three layers deep, like a little rock isle. The more it grows, the slower and harder it becomes.","k":"Sea Turtle","h":"c8m2j"},
"UP-G3-17": {"n":"Lagoon Grand Dugong","f":"Now a single breath warms the lagoon. It carries three wounded on its back at once.","k":"Dugong","h":"nrh5y3"},
"UP-G3-18": {"n":"Coral Spout Tuner","f":"Its branches grew into three. Now it levels three waterspouts and raises them like one wall.","k":"Coral Spirit","h":"1wzca72"},
"UP-G3-24": {"n":"Blackmane Kelpie","f":"After countless whirlpools its mane turned black as the deep. Now the current spins after its hooves.","k":"Kelpie","h":"147tq0i"},
"UP-PN-B3-C2": {"n":"Tamed Capacitor","f":"The runaway capacitor got reins. Now it blows only as much as needed.","k":"Capacitor","h":"mtl62n"},
"US-A1-1": {"n":"Silent Scale","t":"[Offering 4] Destroy 2 enemy units with the highest ATK.","f":"The scale of Morkas, the Silent Lord. Lay blood on one pan, and two lives drop from the other.","b":"{Offering} Life 4|{Foe top ATK 2} Destroy","h":"olthjm"},
"US-A1-2": {"n":"Shadow Pact","t":"[Offering 1] 1 enemy unit with the highest ATK: HP −3. 3 allied units: ATK +3, [Lethal], [Chain].","f":"A copy of the first contract Azra the Shadowless is said to have made. What she staked on the original is not written.","b":"{Foe top ATK 1} ♥−3 · Offering 1|{Ally units 3} ⚔+3 [Lethal] [Chain]","h":"cwwoo2"},
"US-A2-1": {"n":"Radiant Blade","t":"All allies: ATK +2, [Bypass].","f":"The day Solante, Mother of Dawn, put a sword even in the shield hand. A blade forged of light does not see armor.","b":"{All allies} ⚔+2 [Bypass]","h":"1rv2eq6"},
"US-A2-2": {"n":"Solar Judgment","t":"The 2 enemy units with the highest ATK: HP −4. Allied front unit gains [Barrier].","f":"A verdict passed only when the sun stands highest. Those who raise their blades highest burn first.","b":"{Top-ATK foes 2} ♥−4|{Ally front 1} [Barrier]","h":"1qv5b0h"},
"US-A3-1": {"n":"New Moon Contract","t":"All units in the enemy's Hand: ATK −1, HP −1 (for the rest of the match). A unit whose HP reaches 0 is burned. Curseproof stats are not reduced. Draw 1 card (no Life cost).","f":"A contract made in Noctar on a new-moon night bears the foe's name too. The signer holds one more card; the named one's hand withers in their grip.","b":"{Foe Hand} All units ⚔−1 ♥−1|Draw 1 card","h":"7en7et"},
"US-A3-2": {"n":"Eye of Belumir","t":"All enemy units: ATK −2, HP −2. The enemy front 2 units neither attack nor counter this turn.","f":"Belumir, god of the thousand-eyed robe, looks down on the field once. Hands holding blades halt under that gaze.","b":"{All foes} ⚔−2 ♥−2|{Foe front 2} no attack/counter","h":"1xetdal"},
"US-B1-1": {"n":"Chain Explosion","t":"Enemy front unit: HP −4. If it is defeated, all enemy units: HP −2.","f":"When a powder porter falls, its load blows too. Fortan's artillery calls it tactics.","b":"{Foe front 1} ♥−4|{All foes} if defeated ♥−2","h":"125osqb"},
"US-B1-2": {"n":"Dormak Bombardment","t":"All enemy units: HP −2, twice. [Reload 1]","f":"Shells heated in the Heartfire of the giant Dormak beneath the Firecrown Range. Fired once, they burst twice.","b":"{All foes} ♥−2 ×2","h":"1mwvt86"},
"US-B2-1": {"n":"Ironframe Hammer","t":"All allies: DEF +1. Then reduce the opponent's front unit's HP by the total DEF of your units. Any excess after it is defeated carries to the next unit.","f":"The golems line up and become one hammer. Made of iron mined from Sorgrim's arm.","b":"{All allies} ⛨+1|{Foes from front} ♥− total ally ⛨ (excess carries)","h":"1dj8iw1"},
"US-B2-2": {"n":"Steel March","t":"All allies: ATK + (number of allied units).","f":"When Durkheim's golems march in step, the Ironframe Range rings. With each one added, every hammer grows that much heavier.","b":"{All allies} ⚔ + ally unit count","h":"8gy1se"},
"US-B3-1": {"n":"Lightning Rampage","t":"Random enemy unit: HP −1, 6 times.","f":"The day all of Voltarium's jars broke at once. Not even the lightning knows where it will go.","b":"{Foe random} ♥−1 ×6","h":"3tncib"},
"US-B3-2": {"n":"Keraun's Nerves","t":"From the front of the enemy Line, in order: HP −4 → −3 → −3 → −2.","f":"Someone touched the nerves of the giant Keraun, asleep beneath the plateau. Lightning leaps up in rows.","b":"{Foe from front} In order ♥−4→−3→−3→−2","h":"1ep2wq1"},
"US-G1-1": {"n":"Challenge to Duel","t":"Front allied unit: ATK +4. It strikes the 1 enemy unit with the highest ATK first (physical damage). If that unit survives, it strikes back.","f":"Garun's orcs throw their blade at the strongest first. That is the law Karno Ashmane left after a hundred duels.","b":"{Ally front 1} ⚔+4|{Top-ATK foe 1} duel, strike first","h":"1yrhckj"},
"US-G1-2": {"n":"Wrath of the Earth","t":"All allies: ATK +2. All enemy units: HP −(allied units).","f":"When the pack stamps as one, Gorvath, Dragon of Earth, stirs in his sleep.","b":"{All allies} ⚔+2|{All foes} ♥− allied units","h":"eg8zo"},
"US-G2-1": {"n":"Grove of Regrowth","t":"1 allied unit: HP +3, [Thorns 2].","f":"Where Drien, the great forest spirit, has passed. Severed branches rejoin on the spot, and thorns sprout at every seam.","b":"{Ally 1} ♥+3 [Thorns 2]","h":"14isq47"},
"US-G2-2": {"n":"Elder Tree's Wrath","t":"Each allied unit: ATK + (half its remaining HP, round up).","f":"When Verdan, the forest dragon, rages, thousand-year trees walk out roots and all. Their long years become their weight.","b":"{All allies} ⚔ + half own ♥","h":"pb2id6"},
"US-G3-1": {"n":"Song of Nelia","t":"All enemy units lose [Barrier]·[Thorns]·[Curseproof]·[Guard], and their Coins turn tails (Coins already decided stay). All enemy units: HP −1. Your front-most unit gains [Purify] this turn.","f":"The song of Nelia, great spirit of water. Like water taking its vessel's shape, it washes away every adornment of those who hear.","b":"{All foes} abilities off · Coins tails|{All foes} ♥−1|{Ally front 1} [Purify]","h":"1xdt4zd"},
"US-G3-2": {"n":"Return of the Tide","t":"All enemy units: HP −2. All allies: HP +1. Your front-most unit gains [Heal 1] this turn.","f":"The sea that ebbed with Talakus's pulse returns. Foes are swept away; allies are washed clean.","b":"{All foes} ♥−2|{All allies} ♥+1|{Ally front 1} [Heal 1]","h":"3o2wki"}
};
